	[Guid("8063832a-c634-4579-aa8b-86aaa0948d45")]
	public class AdbBalanceSheet : AdbBase
	{
		public const string OverallMaterialIdent = "484d4f3c-21aa-45ab-ac68-56d2a3d40b1f";

		[AdbFieldIdent("484d4f3c-21aa-45ab-ac68-56d2a3d40b1f")]
		public AdbMaterialBalance OverallMaterial;

		public const string OverallEnergyIdent = "21ad6ce1-0ec6-44e9-bff6-b60da036da50";

		[AdbFieldIdent("21ad6ce1-0ec6-44e9-bff6-b60da036da50")]
		public AdbEnergyBalance OverallEnergy;

		public const string ComponentMaterialIdent = "965c0ca5-6b8c-46d5-9d88-2ad0f91ea5a2";

		[AdbFieldIdent("965c0ca5-6b8c-46d5-9d88-2ad0f91ea5a2")]
		public AdbBaseArray<AdbComponent, AdbMaterialBalance> ComponentMaterial;

		public AdbBalanceSheet(AdbTop top, Guid? existingGuid)
			: base(top, existingGuid)
		{
			if (OverallMaterial != null)
			{
				OverallMaterial = null;
			}
			if (OverallEnergy != null)
			{
				OverallEnergy = null;
			}
			if (ComponentMaterial != null)
			{
				ComponentMaterial.Clear(deleteRecords: true);
			}
		}

		public override void CleanUp()
		{
			base.CleanUp();
			if (ComponentMaterial != null)
			{
				ComponentMaterial.Clear(deleteRecords: true);
				ComponentMaterial = null;
			}
			if (OverallMaterial != null)
			{
				OverallMaterial.CleanUp();
				_top.RecordMap.Remove(OverallMaterial.MyGuid, -1L);
				_top.NotifyOnRecordDelete(OverallMaterial);
				OverallMaterial = null;
			}
			if (OverallEnergy != null)
			{
				OverallEnergy.CleanUp();
				_top.RecordMap.Remove(OverallEnergy.MyGuid, -1L);
				_top.NotifyOnRecordDelete(OverallEnergy);
				OverallEnergy = null;
			}
		}
	}
