		{
			CurrentStep = step;
			CurrentKineticResults = result;
		}

		public override void CleanUp()
		{
			base.CleanUp();
			LocCleanUp();
		}

		[AdbMethodIdent("257e0314-ca27-441c-b398-9e69bc238e31")]
		public void LocCleanUp()
		{
			if (ProfileKinetics != null)
			{
				ProfileKinetics.Clear(deleteRecords: true);
				ProfileKinetics = null;
			}
			if (CurrentKineticResults != null)
			{
				CurrentKineticResults.CleanUp();
				_top.RecordMap.Remove(CurrentKineticResults.MyGuid, -1L);
				_top.NotifyOnRecordDelete(CurrentKineticResults);
				CurrentKineticResults = null;
			}
		}
	}
	[ComVisible(true)]
	[Guid("C248FF3E-38BF-473C-AF1B-0CD684D65792")]
	public class AdbPumpCompBase : AdbUoBlock
	{
		public AdbPumpCompBase(AdbTop top, Guid? existingGuid)
			: base(top, existingGuid)
		{
		}

		public AdbPumpCompBase(AdbTop top)
			: base(top)
		{
		}

		public AdbPumpCompBase()
		{
		}

		protected virtual AdbBaseRecord CreateCurve()
		{
			return null;
		}

		public T FindCurve<T>(double shaftSpeed, ref AdbBaseArray<string, T> curves) where T : AdbPumpCurve
		{
			T val = null;
			if (curves == null)
			{
				curves = new AdbBaseArray<string, T>(base.Top, this);
			}
			int num = curves.Length;
			for (int i = 0; i < num; i++)
			{
				if (val != null)
				{
					break;
				}
				T val2 = null;
				while (val2 == null && i < num)
				{
					object obj = curves.ValueAtLocation(i);
					if (obj == null)
					{
						curves.RemoveAtLocation(i);
						num--;
						continue;
					}
					val2 = obj as T;
					if (val2 == null)
					{
						curves.RemoveAtLocation(i);
						if (obj is AdbBaseRecord adbBaseRecord)
						{
							adbBaseRecord.DeleteMe(-1L);
						}
						num--;
					}
					else if (!val2.ShaftSpeed.HasValue)
					{
						curves.RemoveAtLocation(i);
						val2.DeleteMe(-1L);
						val2 = null;
						num--;
					}
				}
				if (Math.Abs(val2.ShaftSpeed.Value - shaftSpeed) < 1E-05)
				{
					val = val2;
				}
				else if (val2.ShaftSpeed.Value > shaftSpeed)
				{
					val = CreateCurve() as T;
					val.ShaftSpeed = shaftSpeed;
					for (int j = i; j < num; j++)
					{
						curves.SetID(i, (j + 2).ToString());
					}
					curves.InsertBeforeLocation(i, (i + 1).ToString(), val);
				}
			}
			if (val == null)
			{
				val = CreateCurve() as T;
				val.ShaftSpeed = shaftSpeed;
				curves.Append((num + 1).ToString(), val);
			}
			return val;
		}

		protected void AddCvpt<T>(double shaftSpeed, double flow, double? head, double? eff, ref AdbBaseArray<string, T> curves) where T : AdbPumpCurve
		{
			FindCurve(shaftSpeed, ref curves).AddPoint(flow, head, eff);
		}
	}
