		public override void CleanUp()
		{
			base.CleanUp();
			LocCleanUp();
		}

		[AdbMethodIdent("8c4497c2-b05d-4e8a-8d8a-375937ce461f")]
		public void LocCleanUp()
		{
			if (WeightFractions != null)
			{
				WeightFractions.Clear(deleteRecords: true);
				WeightFractions = null;
			}
			if (CumulativeWeightFractions != null)
			{
				CumulativeWeightFractions.Clear(deleteRecords: true);
				CumulativeWeightFractions = null;
			}
			if (AverageParticleDiameters != null)
			{
				AverageParticleDiameters.Clear(deleteRecords: true);
				AverageParticleDiameters = null;
			}
			if (Mesh != null)
			{
				Mesh.CleanUp();
