		private void SetValue(string id, double dVal)
		{
			for (int i = 0; i < base.GetFieldList.Count; i++)
			{
				FieldInfo f = base.GetFieldList[i].F;
				if (string.Compare(f.Name, id, ignoreCase: true) == 0)
				{
					if (!dVal.ToString().EndsWith("E+35") && dVal > 0.0)
					{
						f.SetValue(this, dVal);
					}
					else
					{
						f.SetValue(this, double.NaN);
					}
					break;
				}
			}
		}
	}
