		private void _extraProperties_OnClearedProperty(AdbPropertyHolder.OnClearPropertyEventArg arg)
		{
			if (!string.IsNullOrEmpty(arg.Property))
			{
				return;
			}
			if (arg.Property == "MASSHMX")
			{
				SetScalarValue("60b637f6-f3ac-4f69-ad5c-3308ff01201e", null);
				return;
			}
			if (arg.Property == "HMX")
			{
				SetScalarValue("298cb9cb-890b-47d3-917b-47fc38a89c7c", null);
				SetScalarValue("60b637f6-f3ac-4f69-ad5c-3308ff01201e", null);
				return;
			}
			if (arg.Property == "MASSVFRA")
			{
				SetScalarValue("403B2C02-AEFB-4743-A291-CE40CF279CCA", null);
				return;
			}
			AdbPhase adbPhase = FindPhaseByAPName(this, arg.Phase, create: false);
			if (adbPhase != null)
			{
				OnPhaseClearProperty(adbPhase, arg);
			}
		}

		private void _extraProperties_OnStoringRd(AdbPropertyHolder.OnStoringRdEventArg arg)
		{
			if (!string.IsNullOrEmpty(arg.row.w))
			{
				return;
			}
			if (arg.row.n == "MASSHMX" && arg.row.ph == "TOTAL")
			{
				SetScalarValue("60b637f6-f3ac-4f69-ad5c-3308ff01201e", arg.newVal);
			}
			else if (arg.row.n == "HMX" && arg.row.ph == "TOTAL")
			{
				if (arg.row.u == 40)
				{
					SetScalarValue("60b637f6-f3ac-4f69-ad5c-3308ff01201e", arg.newVal);
				}
				else if (arg.row.u == 39)
				{
					SetScalarValue("298cb9cb-890b-47d3-917b-47fc38a89c7c", arg.newVal);
				}
			}
			else if (arg.row.n == "MASSVFRA")
			{
				SetScalarValue("403B2C02-AEFB-4743-A291-CE40CF279CCA", arg.newVal);
			}
			else
			{
				AdbPhase adbPhase = FindPhaseByAPName(this, arg.row.ph, create: true);
				if (adbPhase != null)
				{
					OnPhaseStoreRow(adbPhase, arg);
				}
			}
		}

