		private AdbPhase FindPhaseByAPName(AdbHeatCurvePoint point, string phaseName, bool create)
		{
			if (point == null)
			{
				return null;
			}
			AdbPhase adbPhase = null;
			if (phaseName == "VAPOR")
			{
				adbPhase = point.Vapor;
				if (adbPhase == null && create)
				{
					adbPhase = new AdbPhase(base.Top, null);
					point.SetScalarValue("fc35cadd-a1d0-4ffe-bb26-1914b4b9bd83", adbPhase);
				}
			}
			else if (phaseName == "LIQUID")
			{
				adbPhase = point.Liquid;
				if (adbPhase == null && create)
				{
					adbPhase = new AdbPhase(base.Top, null);
					point.SetScalarValue("ef80b5d2-3e59-4371-b401-a83d80d2d405", adbPhase);
				}
			}
			return adbPhase;
		}

