		public virtual double? GetTotalFeedMassFlow()
		{
			if (LiquidFeed != null || VaporFeed != null || MixedFeed != null)
			{
				double num = 0.0;
				if (LiquidFeed != null)
				{
					if (!LiquidFeed.GetResolvedMassFlow().HasValue)
					{
						return null;
					}
					num += LiquidFeed.GetResolvedMassFlow().Value;
				}
				if (VaporFeed != null)
				{
					if (!VaporFeed.GetResolvedMassFlow().HasValue)
					{
						return null;
					}
					num += VaporFeed.GetResolvedMassFlow().Value;
				}
				if (MixedFeed != null)
				{
					if (!MixedFeed.GetResolvedMassFlow().HasValue)
					{
						return null;
					}
					num += MixedFeed.GetResolvedMassFlow().Value;
				}
				return num;
			}
			return null;
		}

