		[AdbFieldIdent("d20da2d1-9f38-4c8d-8f93-4232e91f5c48")]
		public string ProfileType;

		public const string ProfileListIdent = "7E50DBBA-665E-49F1-89B1-D5362391BC97";

		[AdbFieldIdent("7E50DBBA-665E-49F1-89B1-D5362391BC97")]
		public AdbBaseArray<int, AdbVarList> profileList;

		public const string ArrayProfileIdent = "46395bf4-1184-46d7-9702-7a8017fa20d8";

		[AdbFieldIdent("46395bf4-1184-46d7-9702-7a8017fa20d8")]
		public AdbBaseArray<int, AdbArrayList> ArrayProfile;

		public const string SetProfileTypeIdent = "20164ed2-2dd2-4c4c-a7b6-6654b43cf86b";

		public const string AddValueIdent = "CB027633-2F84-474C-B255-DC91F0944575";

		public const string SetMostRecentTimeIdent = "252EEEC3-9FA0-42E2-9963-426AFDCCD55E";

		public const string IncrementCounterIdent = "E12CAF12-4AA3-4B82-B40B-C357739CEA13";

		public const string ResetCounterIdent = "F98F4096-2D19-4143-A82F-F020F6ACD490";

		public AdbVarListTimeProfile(AdbTop top, Guid? existingGuid)
			: base(top, existingGuid)
		{
			CurrentIntegratorStep = 0;
			SimulationTime = 0.0;
			MaxProfileHistory = 50000;
			HasLooped = false;
			profileList = new AdbBaseArray<int, AdbVarList>(base.Top, this);
			ArrayProfile = new AdbBaseArray<int, AdbArrayList>(base.Top, this);
			ProfileType = "VarList";
			Loops = 0;
		}

		[AdbMethodIdent("20164ed2-2dd2-4c4c-a7b6-6654b43cf86b")]
		public void SetProfileType(int type)
		{
			if (type == 1)
			{
				ProfileType = "Array";
			}
			else
			{
				ProfileType = "VarList";
			}
			if (profileList != null)
			{
				profileList.Clear(deleteRecords: true);
			}
			if (ArrayProfile != null)
			{
				ArrayProfile.Clear(deleteRecords: true);
			}
			ResetCounter();
		}

		[AdbMethodIdent("CB027633-2F84-474C-B255-DC91F0944575")]
		public void AddValue(string varName, double varValue, int pType)
		{
			if (ProfileType == "Array")
			{
				if (ArrayProfile == null)
				{
					ArrayProfile = new AdbBaseArray<int, AdbArrayList>(base.Top, this);
				}
				if (ArrayProfile.ValueAt(CurrentIntegratorStep) == null)
				{
					ArrayAppend("46395bf4-1184-46d7-9702-7a8017fa20d8", CurrentIntegratorStep, new AdbArrayList(_top, null));
				}
				(ArrayProfile.ValueAt(CurrentIntegratorStep) as AdbArrayList).FillArrayList(varName, varValue, pType);
			}
			else
			{
				if (profileList == null)
				{
					profileList = new AdbBaseArray<int, AdbVarList>(base.Top, this);
				}
				if (profileList.ValueAt(CurrentIntegratorStep) == null)
				{
					ArrayAppend("7E50DBBA-665E-49F1-89B1-D5362391BC97", CurrentIntegratorStep, new AdbVarList(_top, null));
				}
				(profileList.ValueAt(CurrentIntegratorStep) as AdbVarList).AddVariableValue(varName, varValue, pType);
			}
		}

		[AdbMethodIdent("252EEEC3-9FA0-42E2-9963-426AFDCCD55E")]
		public void SetMostRecentTime(double t)
		{
			SimulationTime = t;
			if (ProfileType == "Array")
			{
				if (ArrayProfile == null)
				{
					ArrayProfile = new AdbBaseArray<int, AdbArrayList>(base.Top, this);
				}
				if (ArrayProfile.ValueAt(CurrentIntegratorStep) == null)
				{
					ArrayAppend("46395bf4-1184-46d7-9702-7a8017fa20d8", CurrentIntegratorStep, new AdbArrayList(_top, null));
				}
				(ArrayProfile.ValueAt(CurrentIntegratorStep) as AdbArrayList).CurrentTime = t;
				(ArrayProfile.ValueAt(CurrentIntegratorStep) as AdbArrayList).InitArrays();
			}
			else
			{
				if (profileList == null)
				{
					profileList = new AdbBaseArray<int, AdbVarList>(base.Top, this);
				}
				if (profileList.ValueAt(CurrentIntegratorStep) == null)
				{
					ArrayAppend("7E50DBBA-665E-49F1-89B1-D5362391BC97", CurrentIntegratorStep, new AdbVarList(_top, null));
				}
				(profileList.ValueAt(CurrentIntegratorStep) as AdbVarList).CurrentTime = t;
			}
		}

		[AdbMethodIdent("E12CAF12-4AA3-4B82-B40B-C357739CEA13")]
		public void IncrementCounter()
		{
			if (++CurrentIntegratorStep >= MaxProfileHistory)
			{
				CurrentIntegratorStep = 0;
				HasLooped = true;
				Loops++;
			}
		}

		[AdbMethodIdent("F98F4096-2D19-4143-A82F-F020F6ACD490")]
		public void ResetCounter()
		{
			SimulationTime = 0.0;
			CurrentIntegratorStep = 0;
			HasLooped = false;
			Loops = 0;
			if (profileList != null)
			{
				profileList.Clear(deleteRecords: true);
			}
			if (ArrayProfile != null)
			{
				ArrayProfile.Clear(deleteRecords: true);
			}
			SetNewChange();
		}

		public override void CleanUp()
		{
			base.CleanUp();
			if (profileList != null)
			{
				profileList.Clear(deleteRecords: true);
				profileList = null;
			}
			if (ArrayProfile != null)
			{
				ArrayProfile.Clear(deleteRecords: true);
				ArrayProfile = null;
			}
		}
	}
