		[AdbMethodIdent("F545AFFA-5FF7-43D0-88AC-E9296673DC33")]
		public void StorePropertySPTQ(string name, string substream, string phase, double tempbasis, string units, double value, int refType, double referencePressure)
		{
			AdbRowDesc adbRowDesc = null;
			switch (refType)
			{
			default:
				adbRowDesc = new AdbRowDesc
				{
					n = name,
					s = substream,
					ph = phase,
					t = tempbasis
				};
				break;
			case 1:
			case 3:
				adbRowDesc = new AdbRowDesc
				{
					n = name,
					s = substream,
					ph = phase,
					t = tempbasis,
					pr = referencePressure
				};
				break;
			case 4:
				adbRowDesc = new AdbRowDesc
				{
					n = name,
					s = substream,
					ph = phase,
					t = tempbasis,
					w = "DRY"
				};
				break;
			case 5:
			case 7:
				adbRowDesc = new AdbRowDesc
				{
					n = name,
					s = substream,
					ph = phase,
					t = tempbasis,
					pr = referencePressure,
					w = "DRY"
				};
				break;
			}
			StoreRd(adbRowDesc, value);
		}

