		[AdbMethodIdent("17EE548B-878D-42AF-AD20-2D197424C2C3")]
		public void ClearAll()
		{
			if (myPropertyTable != null)
			{
				myPropertyTable.Clear();
				SetNewChange();
			}
		}

		[AdbMethodIdent("279CAB19-265F-473C-B881-B7EB28EA09ED")]
		public void ClearProperty(string name)
		{
			if (myPropertyTable == null)
			{
				return;
			}
			string filterExpression = "Name = '" + name + "'";
			DataRow[] array = myPropertyTable.Select(filterExpression);
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Delete();
			}
			try
			{
				if (this.OnClearedProperty != null)
				{
					this.OnClearedProperty(new OnClearPropertyEventArg(name));
				}
			}
			catch (Exception)
			{
			}
			SetNewChange();
		}

		[AdbMethodIdent("B32C468F-06C3-4859-AC76-09606592D769")]
		public void ClearPropertyS(string name, string substream)
		{
			if (myPropertyTable == null)
			{
				return;
			}
			string filterExpression = "Name = '" + name + "' AND Substream = '" + substream + "'";
			DataRow[] array = myPropertyTable.Select(filterExpression);
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Delete();
			}
			try
			{
				if (this.OnClearedProperty != null)
				{
					this.OnClearedProperty(new OnClearPropertyEventArg(name)
					{
						Substream = substream
					});
				}
			}
			catch (Exception)
			{
			}
			SetNewChange();
		}

