		[AdbMethodIdent("57894CF4-9E41-4332-A469-E8156830B328")]
		public void ClearPropSPBasisRef(string name, string substream, string phase, int refType, double tref, double pref)
		{
			string text = "Name = '" + name + "' AND Substream = '" + substream + "' AND Phase = '" + phase + "' AND WetDry = ''";
			if (refType > 3)
			{
				text = "Name = '" + name + "' AND Substream = '" + substream + "' AND Phase = '" + phase + "' AND WetDry = 'DRY'";
			}
			if (refType == 1 || refType == 2 || refType == 5 || refType == 6)
			{
				text = text + " AND TempBasis = '" + tref + "'";
			}
			if (refType == 1 || refType == 3 || refType == 5 || refType == 7)
			{
				text = text + " AND PressureBasis = '" + pref + "'";
			}
			DataRow[] array = myPropertyTable.Select(text);
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Delete();
			}
			try
			{
				if (this.OnClearedProperty != null)
				{
					this.OnClearedProperty(new OnClearPropertyEventArg(name)
					{
						Substream = substream,
						Phase = phase,
						Basis = ((refType >= 4) ? 1 : 0)
					});
				}
			}
			catch (Exception)
			{
			}
			SetNewChange();
		}

