			case 1:
			case 3:
				adbRowDesc = new AdbRowDesc
				{
					n = name,
					s = substream,
					ph = phase,
					t = tempbasis,
					u = units,
					pr = referencePressure
				};
				break;
			case 4:
				adbRowDesc = new AdbRowDesc
				{
					n = name,
					s = substream,
					ph = phase,
					t = tempbasis,
					u = units,
					w = "DRY"
				};
				break;
			case 5:
			case 7:
				adbRowDesc = new AdbRowDesc
				{
					n = name,
					s = substream,
					ph = phase,
					t = tempbasis,
					u = units,
					pr = referencePressure,
					w = "DRY"
				};
				break;
			}
			StoreRd(adbRowDesc, value);
		}

