		internal bool HasSubstreamPhaseProps(string substream, string phase)
		{
			string filterExpression = "Substream = '" + substream + "' AND Phase = '" + phase + "'";
			DataRow[] array = myPropertyTable.Select(filterExpression);
			if (array != null)
			{
				return array.Length != 0;
			}
			return false;
		}
	}
