	[Guid("5C257976-0B1E-419C-A398-262E4E1C3315")]
	public class AdbPumpCurve : AdbBase
	{
		public const string ShaftSpeedIdent = "1d516a1f-5b4a-42a2-a5dd-98af8da8618c";

		[AdbFieldIdent("1d516a1f-5b4a-42a2-a5dd-98af8da8618c", PhysicalType = PhysicalType.Frequency)]
		public double? ShaftSpeed;

		public const string PointsIdent = "2d0b9aa2-c14b-46a3-a03d-633a4eb9f7af";

		[AdbFieldIdent("2d0b9aa2-c14b-46a3-a03d-633a4eb9f7af")]
		public AdbBaseArray<string, AdbPumpCurvePoint> Points;

		public AdbPumpCurve(AdbTop top, Guid? existingGuid)
			: base(top, existingGuid)
		{
		}

		public AdbPumpCurve(AdbTop top)
			: base(top)
		{
		}

		public AdbPumpCurve()
		{
		}

		[AdbMethodIdent("EAEA35B7-E7E9-44A4-9FAB-3D01608E2A2F")]
		public void RemovePoint(int location)
		{
			if (Points != null && location < Points.Length)
			{
				((AdbPumpCurvePoint)Points.ValueAtLocation(location))?.DeleteMe(-1L);
				Points.RemoveAtLocation(location);
				for (int i = location; i < Points.Length; i++)
				{
					Points.SetID(i, (i + 1).ToString());
				}
			}
		}

		public void AddPoint(double flow, double? head, double? eff)
		{
			AdbPumpCurvePoint adbPumpCurvePoint = null;
			if (Points == null)
			{
				Points = new AdbBaseArray<string, AdbPumpCurvePoint>(base.Top, this);
			}
			int num = Points.Length;
			for (int i = 0; i < num; i++)
			{
				if (adbPumpCurvePoint != null)
				{
					break;
				}
				AdbPumpCurvePoint adbPumpCurvePoint2 = null;
				while (adbPumpCurvePoint2 == null && i < num)
				{
					object obj = Points.ValueAtLocation(i);
					if (obj == null)
					{
						Points.RemoveAtLocation(i);
						num--;
						continue;
					}
					adbPumpCurvePoint2 = obj as AdbPumpCurvePoint;
					if (adbPumpCurvePoint2 == null)
					{
						Points.RemoveAtLocation(i);
						if (obj is AdbBaseRecord adbBaseRecord)
						{
							adbBaseRecord.DeleteMe(-1L);
						}
						num--;
					}
					else if (!adbPumpCurvePoint2.Flow.HasValue)
					{
						Points.RemoveAtLocation(i);
						adbPumpCurvePoint2.DeleteMe(-1L);
						adbPumpCurvePoint2 = null;
						num--;
					}
				}
				if (Math.Abs(adbPumpCurvePoint2.Flow.Value - flow) < 1E-10)
				{
					adbPumpCurvePoint = adbPumpCurvePoint2;
				}
				else if (adbPumpCurvePoint2.Flow.Value > flow)
				{
					adbPumpCurvePoint = new AdbPumpCurvePoint(base.Top, null);
					adbPumpCurvePoint.Flow = flow;
					for (int j = i; j < num; j++)
					{
						Points.SetID(j, (j + 2).ToString());
					}
					Points.InsertBeforeLocation(i, (i + 1).ToString(), adbPumpCurvePoint);
				}
			}
			if (adbPumpCurvePoint == null)
			{
				adbPumpCurvePoint = new AdbPumpCurvePoint(base.Top, null);
				adbPumpCurvePoint.Flow = flow;
				Points.Append((num + 1).ToString(), adbPumpCurvePoint);
			}
			if (head.HasValue)
			{
				adbPumpCurvePoint.Head = head;
			}
			if (eff.HasValue)
			{
				adbPumpCurvePoint.Efficiency = eff;
			}
		}

		public virtual AdbBaseRecord Create(AdbTop top)
		{
			return new AdbPumpCurve(top, null);
		}

		[AdbMethodIdent("B11A5119-C601-41F1-873E-96C145714AAD")]
		public void SetValuesInPoint(int location, double flow, double head, double eff)
		{
			if (location < Points.Length)
			{
				((AdbPumpCurvePoint)Points.ValueAtLocation(location)).SetPoint(flow, head, eff);
			}
		}
	}
