		public override void CleanUp()
		{
			if (HydraulicResults != null)
			{
				HydraulicResults.CleanUp();
				_top.RecordMap.Remove(HydraulicResults.MyGuid, -1L);
				_top.NotifyOnRecordDelete(HydraulicResults);
				HydraulicResults = null;
			}
			if (TrayGeometryData != null)
			{
				TrayGeometryData.CleanUp();
				_top.RecordMap.Remove(TrayGeometryData.MyGuid, -1L);
				_top.NotifyOnRecordDelete(TrayGeometryData);
				TrayGeometryData = null;
			}
			SectionKey = null;
			SectionName = null;
			DiagramSectionDataXML = null;
			SectionResultDataXML = null;
		}
