		{
		}

		public override void CleanUp()
		{
			if (Weirs != null)
			{
				for (int i = 0; i < Weirs.Length; i++)
				{
					if (Weirs.ValueAtLocation(i) is AdbCAWeirResultData adbCAWeirResultData)
					{
						_top.RecordMap.Remove(adbCAWeirResultData.MyGuid, -1L);
						_top.NotifyOnRecordDelete(adbCAWeirResultData);
					}
				}
				Weirs = new AdbBaseArray<int, AdbCAWeirResultData>(base.Top, this);
			}
			if (SideDowncomers != null)
			{
				_top.RecordMap.Remove(SideDowncomers.MyGuid, -1L);
				_top.NotifyOnRecordDelete(SideDowncomers);
			}
			if (CenterSideDowncomers != null)
			{
				_top.RecordMap.Remove(CenterSideDowncomers.MyGuid, -1L);
				_top.NotifyOnRecordDelete(CenterSideDowncomers);
			}
			if (OffCenterDowncomers != null)
			{
				_top.RecordMap.Remove(OffCenterDowncomers.MyGuid, -1L);
				_top.NotifyOnRecordDelete(OffCenterDowncomers);
			}
			if (MDDowncomers != null)
			{
				_top.RecordMap.Remove(MDDowncomers.MyGuid, -1L);
				_top.NotifyOnRecordDelete(MDDowncomers);
			}
		}
	}
