		[AdbMethodIdent("A612CDA8-58F8-4D80-AF25-FD2BEF25F0F6")]
		public void AddStyleSheet(string lTagId)
		{
			StreamStyleSheetList.Append(lTagId, new AdbStreamStyleSheet(lTagId));
		}

		[AdbMethodIdent("AB1BA1BD-0EA5-4D2F-B3E6-E682436F8CFB")]
		public void AddStyleSheetTagAndMode(string lTagId, int lMode)
		{
			StreamStyleSheetList.Append(lTagId, new AdbStreamStyleSheet(lTagId, lMode));
		}

		[AdbMethodIdent("A10F1D93-D99D-4FC7-B664-551E735903D7")]
		public void CopyStyleSheet(string src_lTagId, string dst_TagId)
		{
			AdbStreamStyleSheet adbStreamStyleSheet = FindStyleSheetByTag(src_lTagId);
			if (adbStreamStyleSheet != null && adbStreamStyleSheet.GridMode == 12)
			{
				AdbStreamStyleSheet adbStreamStyleSheet2 = new AdbStreamStyleSheet(dst_TagId);
				adbStreamStyleSheet2.KeyValuePairs = adbStreamStyleSheet.KeyValuePairs;
				adbStreamStyleSheet2.GridMode = adbStreamStyleSheet.GridMode;
				StreamStyleSheetList.Append(dst_TagId, adbStreamStyleSheet2);
			}
		}

		[AdbMethodIdent("F14585BE-AAF0-4441-AB80-714F109803CE")]
		public AdbStreamStyleSheet FindStyleSheetByTag(string lTagId)
		{
			AdbStreamStyleSheet result = null;
			if (StreamStyleSheetList != null)
			{
				result = StreamStyleSheetList.ValueAt(lTagId) as AdbStreamStyleSheet;
			}
			return result;
		}

		[AdbMethodIdent("8FA41330-B746-485C-A61D-FCAB8A42CA4D")]
		public AdbStreamStyleSheet FindStyleSheetByIndex(int index)
		{
			AdbStreamStyleSheet result = null;
			if (StreamStyleSheetList != null)
			{
				result = StreamStyleSheetList.ValueAtLocation(index) as AdbStreamStyleSheet;
			}
			return result;
		}

		[AdbMethodIdent("995B0EC8-DB2C-43FF-B900-8F47EBA822EB")]
		public string GetSSQueryString(int index)
		{
			string result = null;
			if (StreamStyleSheetList != null)
			{
				AdbStreamStyleSheet adbStreamStyleSheet = StreamStyleSheetList.ValueAtLocation(index) as AdbStreamStyleSheet;
				if (adbStreamStyleSheet == null)
				{
					result = adbStreamStyleSheet.GetKeyValue("APCSV");
				}
			}
			return result;
		}

		[AdbMethodIdent("95652311-C76F-4086-9003-B322495C5AE5")]
		public void StyleSheetMapKeyValue(string sTagId, string sKey, string sValue)
		{
			if (StreamStyleSheetList != null)
			{
				AdbStreamStyleSheet adbStreamStyleSheet = StreamStyleSheetList.ValueAt(sTagId) as AdbStreamStyleSheet;
				if (adbStreamStyleSheet == null)
				{
					adbStreamStyleSheet.SetKeyValuePair(sKey, sValue);
				}
			}
		}

