	[Guid("2004D2C2-0A3C-44A1-B138-9EF107C43232")]
	public class AdbUnitConversion : AdbBase
	{
		[AdbFieldIdent("3ED8C87E-5770-44FB-B826-9F749F0DEC21")]
		public string DisplayName;

		[AdbFieldIdent("6EB99E57-7D76-4C8F-9BAA-AB8C4BE5D61D", Comment1 = "NoConv = 0,NormalConv = 1,TempConv = 2,GPressConv = 3,APIConv = 4,UserConv = 5")]
		public int ConversionType;

		[AdbFieldIdent("FCF237D5-6D25-4171-B32C-A25BF015B19B")]
		public double Factor1;

		[AdbFieldIdent("B71FAF0F-64F8-402C-8B52-09D33F5D064A")]
		public double? Factor2;

		[AdbFieldIdent("065B440A-73CA-4D92-9460-AAAFC04C69E2")]
		public double? Factor3;

		public AdbUnitConversion(AdbTop top, Guid? existingGuid)
			: base(top, existingGuid)
		{
		}

		[AdbMethodIdent("892B0FBD-3F44-4D06-8E73-D45FCF6AC920")]
		public double ConvertTo(double baseValue)
		{
			switch (ConversionType)
			{
			default:
				return baseValue;
			case 1:
				return baseValue * Factor1;
			case 2:
			{
				double num2 = baseValue * Factor1 + Factor2.Value;
				if (Factor2 != 0.0)
				{
					num2 = ((Math.Abs(num2 / Factor2.Value) > 0.01) ? num2 : 0.0);
				}
				return num2;
			}
			case 3:
			{
				double num = baseValue * Factor1 - Factor2.Value;
				if (Factor2 != 0.0)
				{
					num = ((Math.Abs(num / Factor2.Value) > 0.01) ? num : 0.0);
				}
				return num;
			}
			case 4:
				if (baseValue != 0.0)
				{
					return Factor1 * 141.5 / baseValue - 131.5;
				}
				return 0.0;
			case 5:
				if (Factor1 == 1.0)
				{
					return baseValue * Factor2.Value + Factor3.Value;
				}
				if (Factor1 == 2.0 && baseValue != 0.0)
				{
					return Factor2.Value / baseValue + Factor3.Value;
				}
				return baseValue;
			}
		}
	}
