		[AdbMethodIdent("778ebb33-fa07-46d7-8ff8-4791ce4e9129")]
		public void AddValue(string taskName, string runningName, double startTime, double time, string varID, string descrp, double varValue, int ucol, string approach)
		{
			ID = taskName;
			object obj = null;
			if (!string.IsNullOrEmpty(runningName))
			{
				if (stepStartedTime == null)
				{
					stepStartedTime = new AdbBaseArray<string, double>(base.Top, this);
				}
				else
				{
					obj = stepStartedTime.ValueAt(runningName);
				}
				if (obj == null)
				{
					ArrayAppend("6bb1927a-ddb7-4b69-9786-8be590a123bf", runningName, startTime);
				}
				else
				{
					runningStep = null;
				}
				if (stepDoneInfos == null)
				{
					stepDoneInfos = new AdbBaseArray<string, AdbStepDoneInfo>(base.Top, this);
				}
				if (stepDoneInfos.ValueAt(runningName) == null)
				{
					ArrayAppend("3f31fa6e-022f-4374-bcea-fa3dfdfdadf1", runningName, new AdbStepDoneInfo(_top, null, time, varID, descrp, varValue, ucol, approach));
				}
			}
		}

		[AdbMethodIdent("a415cb72-6cfa-4600-801b-6f9101037cbb")]
		public void ForcedDone(string taskName, double time, string reason)
		{
			ID = taskName;
			currentTime = time;
			if (stat == "ON")
			{
				if (stepDoneInfos == null)
				{
					stepDoneInfos = new AdbBaseArray<string, AdbStepDoneInfo>(base.Top, this);
				}
				if (stepDoneInfos.ValueAt(runningStep) == null)
				{
					ArrayAppend("3f31fa6e-022f-4374-bcea-fa3dfdfdadf1", runningStep, new AdbStepDoneInfo(_top, null, time, reason));
				}
				runningStep = null;
				DoneTime = time;
				stat = "DONE";
			}
		}

		[AdbMethodIdent("c39e345b-08cd-4674-9843-dcbff580ae54")]
		public void StartStep(string taskName, string runningName, double time)
		{
			ID = taskName;
			currentTime = time;
			if (!string.IsNullOrEmpty(runningName))
			{
				if (stepStartedTime == null)
				{
					stepStartedTime = new AdbBaseArray<string, double>(base.Top, this);
				}
				if (stepStartedTime.ValueAt(runningName) == null)
				{
					ArrayAppend("6bb1927a-ddb7-4b69-9786-8be590a123bf", runningName, time);
				}
				stat = "ON";
				runningStep = runningName;
			}
			else
			{
				stat = "DONE";
				runningStep = null;
				DoneTime = time;
			}
		}
	}
