			else
			{
				text = guidCache.GetIndexForGuid(TypeGuid).ToString();
			}
			string value = (isRead ? guidCache.GetGuidForIndex(int.Parse(reader["guid"])).ToString() : guidCache.GetIndexForGuid(new Guid(reader["guid"])).ToString());
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("<Record typeGuid=\"");
			stringBuilder.Append(text);
			stringBuilder.Append("\" guid=\"");
			stringBuilder.Append(value);
			stringBuilder.Append("\" change=\"");
			stringBuilder.Append(reader["change"]);
			stringBuilder.Append("\">");
			if (!isRead && base.CreatedForOutput > 0)
			{
				stringBuilder.Append("<O m=\"" + base.CreatedForOutput + "\"/>");
				swreadable?.Write("<Output m=\"" + base.CreatedForOutput + "\"/>");
			}
			while (reader.Read() && (reader.NodeType != XmlNodeType.EndElement || !reader.Name.Equals("Record")))
			{
				if (reader.NodeType != XmlNodeType.Element)
				{
					continue;
				}
				switch (reader.Name)
				{
				case "O":
				{
					if (!isRead)
					{
						break;
					}
					string attribute = reader.GetAttribute("m");
					if (!string.IsNullOrWhiteSpace(attribute))
					{
