		public string EEKey;

		public int OwnerId { get; set; }

		public AdbUoBlock(AdbTop top, Guid? existingGuid)
			: base(top, existingGuid)
		{
			Active = true;
			IsEEMapped = false;
			IsEESized = false;
			IsEEEvaluated = false;
			HasEEMapping = true;
		}

		public AdbUoBlock(AdbTop top)
			: base(top)
		{
		}

		public AdbUoBlock()
		{
		}

		public double SumOfEquipmentCost()
		{
			return SumOfChildren((AdbProjectEquipment e) => e.EquipmentCost ?? 0.0);
		}

		public double SumOfInstalledCost()
		{
			return SumOfChildren((AdbProjectEquipment e) => e.InstalledCost ?? 0.0);
		}

		public double SumOfWeight()
		{
			return SumOfChildren((AdbProjectEquipment e) => e.Weight ?? 0.0);
		}

		public double SumOfInstalledWeight()
		{
			return SumOfChildren((AdbProjectEquipment e) => e.InstalledWeight ?? 0.0);
		}

		public double SumOfUtilityCost()
		{
			return SumOfChildren((AdbProjectEquipment e) => e.UtilityCost ?? 0.0);
		}

		private double SumOfChildrenUtilities()
		{
			double num = 0.0;
			if (SubFlowsheets != null)
			{
				AdbFlowsheet adbFlowsheet = (AdbFlowsheet)SubFlowsheets.ValueAt("Simulation");
				if (adbFlowsheet != null)
				{
					int length = adbFlowsheet.Blocks.Length;
					for (int i = 0; i < length; i++)
					{
						AdbBlock adbBlock = (AdbBlock)adbFlowsheet.Blocks.ValueAtLocation(i);
						AdbUoBlock adbUoBlock = adbBlock as AdbUoBlock;
						if (adbBlock.SubFlowsheets != null && adbBlock.SubFlowsheets.Length > 0)
						{
							num += adbUoBlock.SumOfChildrenUtilities();
						}
					}
				}
				else
				{
					num += AddUtilityCosts(this);
				}
			}
			return num;
		}

		private double AddUtilityCosts(AdbUoBlock b)
		{
			double num = 0.0;
			if (b.Utilitydata == null)
			{
				return num;
			}
			int length = b.Utilitydata.Length;
			for (int i = 0; i < length; i++)
			{
				num += Convert.ToDouble(b.Utilitydata.ValueAtLocation(i));
			}
			return num;
		}

		public void ReinitializeCostValues()
		{
			IsEEMapped = false;
			IsEESized = false;
			IsEEEvaluated = false;
			if (Utilitydata != null)
			{
				Utilitydata.Clear(deleteRecords: true);
			}
		}
	}
