		public AdbCaseOptimizer Optimizer;

		[AdbFieldIdent("65C83B76-40AC-4E65-9FB0-ADB3B0FC924C")]
		public AdbBaseArray<string, AdbCaseStudy> CaseStudies;

		public const string AnalysesIdent = "BD092F92-FAF2-4B04-884C-BFF0A022081C";

		[AdbFieldIdent("BD092F92-FAF2-4B04-884C-BFF0A022081C")]
		public AdbBaseArray<string, AdbAnalysis> Analyses;

		[AdbFieldIdent("A213C0BD-92E9-4388-84C5-A1C6D4549447", Comment1 = "see VarType enum in define.h for unit types")]
		public AdbBaseArray<int, AdbUnitConversion> DefaultDisplayUnits;

		public AdbAhCase(AdbTop top, Guid? existingGuid)
			: base(top, existingGuid)
		{
		}

		[AdbMethodIdent("0E1D4F29-5228-4459-B35E-A52A77465FA2")]
		public void AddAnalysis(AdbAnalysis newAnalysis, string analysisId)
		{
			newAnalysis.SetScalarValue("B3E5B1F4-2666-4C92-847E-417FB20CAD1A", analysisId);
			if (Analyses == null)
			{
				Analyses = new AdbBaseArray<string, AdbAnalysis>(base.Top, this);
			}
			ArrayAppend("BD092F92-FAF2-4B04-884C-BFF0A022081C", analysisId, newAnalysis);
		}

		[AdbMethodIdent("1263DC64-ADAD-4895-9BD7-FC5C710BCD70")]
		public void RenameAnalysis(string analysisOld, string analysisId)
		{
			if (Analyses == null)
			{
				return;
			}
			int num = Analyses.FindID(analysisOld);
			if (num != -1)
			{
				if (Analyses.ValueAt(num) is AdbAnalysis adbAnalysis)
				{
					adbAnalysis.ID = analysisId;
				}
				ArraySetID("BD092F92-FAF2-4B04-884C-BFF0A022081C", num, analysisId);
			}
		}

		[AdbMethodIdent("BAA132AB-FA1A-4E77-9516-852A17D7AD29")]
		public void AddUnitConversion(AdbUnitConversion newUnit, int vartype)
		{
			if (DefaultDisplayUnits == null)
			{
				DefaultDisplayUnits = new AdbBaseArray<int, AdbUnitConversion>(base.Top, this);
			}
			int num = DefaultDisplayUnits.FindID(vartype);
			if (num == -1)
			{
				ArrayAppend("A213C0BD-92E9-4388-84C5-A1C6D4549447", vartype, newUnit);
			}
			else
			{
				ArraySetValueAtLocation("A213C0BD-92E9-4388-84C5-A1C6D4549447", num, newUnit);
			}
		}
	}
