	[Guid("97A49608-65AE-41BA-A038-59089B0C4CEC")]
	public class AdbAPController : AdbController
	{
		[AdbFieldIdent("E2C1FF96-7530-4E15-A912-9B8843804258")]
		public AdbVarListTimeProfile VarListTimeProfile;

		public const string ParameterListIdent = "4b6f41ec-bc58-42cf-a2a4-f7c3bfaec2dd";

		[AdbFieldIdent("4b6f41ec-bc58-42cf-a2a4-f7c3bfaec2dd")]
		public AdbBaseArray<string, AdbSimpleVariable> ParameterList;

		public AdbAPController(AdbTop top, Guid? existingGuid)
			: base(top, existingGuid)
		{
		}

		public override void CleanUp()
		{
			base.CleanUp();
			if (ParameterList != null)
			{
				ParameterList.Clear(deleteRecords: true);
			}
			if (VarListTimeProfile != null)
			{
				VarListTimeProfile.CleanUp();
				_top.RecordMap.Remove(VarListTimeProfile.MyGuid, -1L);
				_top.NotifyOnRecordDelete(VarListTimeProfile);
				VarListTimeProfile = null;
			}
		}
	}
