	[Guid("EBE609C5-C41B-4F79-88A6-ED3C0ABFB958")]
	public class AdbAPMaterialStream : AdbAPStream
	{
		public const string StreamClassIdent = "ee0469d0-adc7-4d6e-8184-e2aa3bd92fb7";

		[AdbFieldIdent("ee0469d0-adc7-4d6e-8184-e2aa3bd92fb7")]
		public string StreamClass;

		public const string HasMixedSolidsIdent = "9e4d7f91-16d7-4368-9dd1-001d57b2b359";

		[AdbFieldIdent("9e4d7f91-16d7-4368-9dd1-001d57b2b359", Getter = "GetHasMixedSolids")]
		public bool? HasMixedSolids;

		public const string HasMixedLiquidIdent = "e0f6ab4b-9705-4997-b96b-90513bef8add";

		[AdbFieldIdent("e0f6ab4b-9705-4997-b96b-90513bef8add", Getter = "GetHasMixedLiquid")]
		public bool? HasMixedLiquid;

		public const string HasMixedVaporIdent = "0fcd8629-83e4-4bda-9cb9-c2d29230f990";

		[AdbFieldIdent("0fcd8629-83e4-4bda-9cb9-c2d29230f990", Getter = "GetHasMixedVapor")]
		public bool? HasMixedVapor;

		public const string HasMixedLiquid1Ident = "3fb22a64-fdf0-4f3b-8d1a-531b8555afcd";

		[AdbFieldIdent("3fb22a64-fdf0-4f3b-8d1a-531b8555afcd", Getter = "GetHasMixedLiquid1")]
		public bool? HasMixedLiquid1;

		public const string HasMixedLiquid2Ident = "578b2727-1ede-4e57-9fd0-451202106ae7";

		[AdbFieldIdent("578b2727-1ede-4e57-9fd0-451202106ae7", Getter = "GetHasMixedLiquid2")]
		public bool? HasMixedLiquid2;

		public AdbAPMaterialStream(AdbTop top, Guid? existingGuid)
			: base(top, existingGuid)
		{
		}

		public virtual bool? GetHasMixedSolids()
		{
			if (Substreams.ValueAt("MIXED") is AdbSubstream adbSubstream && (adbSubstream.MolarFlow ?? 0.0) > 0.0 && (adbSubstream.SolidFraction ?? 0.0) > 0.0)
			{
				return true;
			}
			if (ExtraProperties != null)
			{
				return ExtraProperties.HasSubstreamPhaseProps("MIXED", "SOLID");
			}
			return false;
		}

		public virtual bool? GetHasMixedLiquid()
		{
			if (Substreams.ValueAt("MIXED") is AdbSubstream adbSubstream && (adbSubstream.MolarFlow ?? 0.0) > 0.0 && (adbSubstream.LiquidFraction ?? 0.0) > 0.0)
			{
				return true;
			}
			if (ExtraProperties != null)
			{
				return ExtraProperties.HasSubstreamPhaseProps("MIXED", "LIQUID");
			}
			return false;
		}

		public virtual bool? GetHasMixedVapor()
		{
			if (Substreams.ValueAt("MIXED") is AdbSubstream adbSubstream && (adbSubstream.MolarFlow ?? 0.0) > 0.0 && (adbSubstream.VaporFraction ?? 0.0) > 0.0)
			{
				return true;
			}
			if (ExtraProperties != null)
			{
				return ExtraProperties.HasSubstreamPhaseProps("MIXED", "VAPOR");
			}
			return false;
		}

		public virtual bool? GetHasMixedLiquid1()
		{
			if (Substreams.ValueAt("MIXED") is AdbSubstream adbSubstream && (adbSubstream.MolarFlow ?? 0.0) > 0.0 && (adbSubstream.LiquidFraction ?? 0.0) > 0.0 && (adbSubstream.Beta ?? 1.0) < 1.0 && (adbSubstream.Beta ?? 1.0) != 0.0)
			{
				return true;
			}
			if (ExtraProperties != null)
			{
				return ExtraProperties.HasSubstreamPhaseProps("MIXED", "LIQUID1");
			}
			return false;
		}

		public virtual bool? GetHasMixedLiquid2()
		{
			if (Substreams.ValueAt("MIXED") is AdbSubstream adbSubstream && (adbSubstream.MolarFlow ?? 0.0) > 0.0 && (adbSubstream.LiquidFraction ?? 0.0) > 0.0 && (adbSubstream.Beta ?? 1.0) < 1.0)
			{
				return true;
			}
			if (ExtraProperties != null)
			{
				return ExtraProperties.HasSubstreamPhaseProps("MIXED", "LIQUID2");
			}
			return false;
		}
	}
