	[ComVisible(true)]
	[Guid("793b978d-2b27-44a5-83e1-78e4fa3c068d")]
	public class AdbAPStream : AdbStream
	{
		public const string TearMaximumConvergenceErrorIdent = "698145d9-5a96-48ca-ac2f-ccec7da647bf";

		[AdbFieldIdent("698145d9-5a96-48ca-ac2f-ccec7da647bf")]
		public double? TearMaximumConvergenceError;

		private AdbPropertyHolder _extraProperties;

		public AdbAPStream(AdbTop top, Guid? existingGuid)
			: base(top, existingGuid)
		{
		}

		public AdbAPStream()
		{
		}

		public override void OnSetExtraProperties()
		{
			base.OnSetExtraProperties();
			if (_extraProperties != null)
			{
				_extraProperties.OnStoringRd -= _extraProperties_OnStoringRd;
				_extraProperties.OnClearedProperty -= _extraProperties_OnClearedProperty;
			}
			_extraProperties = ExtraProperties;
			if (_extraProperties != null)
			{
				_extraProperties.OnStoringRd += _extraProperties_OnStoringRd;
				_extraProperties.OnClearedProperty += _extraProperties_OnClearedProperty;
			}
		}

		private void _extraProperties_OnClearedProperty(AdbPropertyHolder.OnClearPropertyEventArg arg)
		{
			if ((arg.Basis ?? 0) == 0)
			{
				AdbSubstream adbSubstream = FindSubstreamByAPName(arg.Substream, create: false);
				if (adbSubstream != null)
				{
					OnSubstreamClearProperty(adbSubstream, arg);
				}
				if (adbSubstream == this && Substreams != null && Substreams.Length == 1 && Substreams.ValueAtLocation(0) is AdbSubstream substream)
				{
					OnSubstreamClearProperty(substream, arg);
				}
			}
		}

		private AdbSubstream FindSubstreamByAPName(string substreamName, bool create)
		{
			if (string.IsNullOrEmpty(substreamName) || substreamName == "TOTAL$" || substreamName == "$TOTAL")
			{
				return this;
			}
			if (Substreams != null)
			{
				if (Substreams.ValueAt(substreamName) is AdbSubstream result)
				{
					return result;
				}
				if (create)
				{
					AdbSubstream adbSubstream = new AdbSubstream(base.Top, null);
					Substreams.Append(substreamName, adbSubstream);
					return adbSubstream;
				}
			}
			return null;
		}

		private AdbPhase FindPhaseByAPName(AdbSubstream substream, string phaseName, bool create)
		{
			if (substream == null)
			{
				return null;
			}
			AdbPhase adbPhase = null;
			switch (phaseName)
			{
			case "VAPOR":
				adbPhase = substream.Vapor;
				if (adbPhase == null && create)
				{
					adbPhase = new AdbPhase(base.Top, null);
					substream.SetScalarValue("2194AFBF-4C01-424A-A598-2D6B41502805", adbPhase);
				}
				break;
			case "LIQUID":
				adbPhase = substream.Liquid;
				if (adbPhase == null && create)
				{
					adbPhase = new AdbPhase(base.Top, null);
					substream.SetScalarValue("9F67ACF5-ECCE-4045-84F0-467FA3DE01BE", adbPhase);
				}
				break;
			case "LIQUID1":
				adbPhase = substream.Liquid1;
				if (adbPhase == null && create)
				{
					adbPhase = new AdbPhase(base.Top, null);
					substream.SetScalarValue("565A9BA8-597C-4394-9361-89564924FE3E", adbPhase);
				}
				break;
			case "LIQUID2":
				adbPhase = substream.Liquid2;
				if (adbPhase == null && create)
				{
					adbPhase = new AdbPhase(base.Top, null);
					substream.SetScalarValue("9F0BD91F-1B59-4473-9F30-CCCF63F6787F", adbPhase);
				}
				break;
			case "SOLID":
				adbPhase = substream.Solid;
				if (adbPhase == null && create)
				{
					adbPhase = new AdbPhase(base.Top, null);
					substream.SetScalarValue("C464AD1E-98D4-4F1D-B563-4F9832104B7C", adbPhase);
				}
				break;
			}
			return adbPhase;
		}

		private void OnSubstreamClearProperty(AdbSubstream substream, AdbPropertyHolder.OnClearPropertyEventArg arg)
		{
			if (string.IsNullOrEmpty(arg.Phase) || arg.Phase == "TOTAL")
			{
				if (arg.Property == "CPCVMX")
				{
					substream.SetScalarValue("B65AD35E-BC15-4F1E-BA4A-0CEE40C516BD", null);
				}
				else if (arg.Property == "RHOMX")
				{
					substream.SetScalarValue("F92F607C-0874-4F5B-90EE-F165EDB8E2AB", null);
				}
				else if (arg.Property == "HMX")
				{
					substream.SetScalarValue("643F1978-21C9-4529-A95C-3F8E52072309", null);
				}
				else if (!(arg.Property == "MUMX"))
				{
					if (arg.Property == "MWMX")
					{
						substream.SetScalarValue("8151F41D-739F-4A81-B8A7-90B9DF5DF93A", null);
					}
					else if (arg.Property == "MASSVFRA")
					{
						substream.SetScalarValue("038B16F2-E3AC-4DBB-92EB-CA9000184A22", null);
					}
					else if (arg.Property == "MASSLFRA")
					{
						substream.SetScalarValue("2a7298f7-e4a9-466d-a406-60acff53a995", null);
					}
					else if (arg.Property == "MASSSFRA")
					{
						substream.SetScalarValue("190E49AC-DA04-4937-A031-36D72D2747D2", null);
					}
					else if (arg.Property == "VFRAC")
					{
						substream.SetScalarValue("5729A872-3FA6-47AD-B309-341A16BCAA62", null);
					}
					else if (arg.Property == "LFRAC")
					{
						substream.SetScalarValue("F47D9357-2C29-4FFF-AD60-E9A0E39A2FE2", null);
					}
					else if (arg.Property == "SFRAC")
					{
						substream.SetScalarValue("C3ECAB21-3CAC-45C0-9709-8AD2313B8457", null);
					}
					else if (arg.Property == "TEMP")
					{
						substream.SetScalarValue("36ADFF82-C12D-4B22-9AC5-1E4BC786ED91", null);
					}
					else if (arg.Property == "PRES")
					{
						substream.SetScalarValue("AAC6DD64-F01F-4EBF-B4C8-57C4B850A9BE", null);
					}
					else if (arg.Property == "VLSTD-FL")
					{
						substream.ArrayClear("204dcc2a-9e06-4983-8c75-8c038ca44f2f", deleteRecords: false);
					}
				}
			}
			else
			{
				AdbPhase adbPhase = FindPhaseByAPName(substream, arg.Phase, create: false);
				if (adbPhase != null)
				{
					OnPhaseClearProperty(adbPhase, arg);
				}
			}
		}

		private void OnPhaseClearProperty(AdbPhase phase, AdbPropertyHolder.OnClearPropertyEventArg arg)
		{
			if (arg.Property == "HMX")
			{
				phase.SetScalarValue("0E343394-D9D8-42C2-98EC-F00C205CA1F1", null);
				phase.SetScalarValue("f22e6757-57f1-4ddd-8322-b91c4fd6bc17", null);
			}
			if (arg.Property == "RHOMX")
			{
				phase.SetScalarValue("E1F2318C-15E8-42FA-9BEB-BB4087158540", null);
				phase.SetScalarValue("a92c19e8-da35-44ae-9c23-d423e323e0ed", null);
			}
			else if (arg.Property == "MUMX")
			{
				phase.SetScalarValue("833B3C75-8BDA-4ED6-9096-C0D9889515C0", null);
