		private void _extraProperties_OnStoringRd(AdbPropertyHolder.OnStoringRdEventArg arg)
		{
			if (string.IsNullOrEmpty(arg.row.w))
			{
				AdbSubstream adbSubstream = FindSubstreamByAPName(arg.row.s, create: true);
				if (adbSubstream != null)
				{
					OnSubstreamStoreRow(adbSubstream, arg);
				}
				if (adbSubstream == this && Substreams != null && Substreams.Length == 1 && Substreams.ValueAtLocation(0) is AdbSubstream substream)
				{
					OnSubstreamStoreRow(substream, arg);
				}
			}
		}

		private void OnSubstreamStoreRow(AdbSubstream substream, AdbPropertyHolder.OnStoringRdEventArg arg)
		{
			if (string.IsNullOrEmpty(arg.row.ph) || arg.row.ph == "TOTAL")
			{
				if (arg.row.n == "CPCVMX")
				{
					substream.SetScalarValue("B65AD35E-BC15-4F1E-BA4A-0CEE40C516BD", arg.newVal);
				}
				else if (arg.row.n == "RHOMX")
				{
					if (arg.row.u != 37 && arg.row.u == 38)
					{
						substream.SetScalarValue("F92F607C-0874-4F5B-90EE-F165EDB8E2AB", arg.newVal);
					}
				}
				else if (arg.row.n == "HMX")
				{
					if (arg.row.u != 39 && arg.row.u == 40)
					{
						substream.SetScalarValue("643F1978-21C9-4529-A95C-3F8E52072309", arg.newVal);
					}
				}
				else
				{
					if (arg.row.n == "MUMX")
					{
						return;
					}
					if (arg.row.n == "MWMX")
					{
						substream.SetScalarValue("8151F41D-739F-4A81-B8A7-90B9DF5DF93A", arg.newVal);
					}
					else if (arg.row.n == "MASSVFRA")
					{
						substream.SetScalarValue("038B16F2-E3AC-4DBB-92EB-CA9000184A22", arg.newVal);
					}
					else if (arg.row.n == "MASSLFRA")
					{
						substream.SetScalarValue("2a7298f7-e4a9-466d-a406-60acff53a995", arg.newVal);
					}
					else if (arg.row.n == "MASSSFRA")
					{
						substream.SetScalarValue("190E49AC-DA04-4937-A031-36D72D2747D2", arg.newVal);
					}
					else if (arg.row.n == "VFRAC")
					{
						substream.SetScalarValue("5729A872-3FA6-47AD-B309-341A16BCAA62", arg.newVal);
					}
					else if (arg.row.n == "LFRAC")
					{
						substream.SetScalarValue("F47D9357-2C29-4FFF-AD60-E9A0E39A2FE2", arg.newVal);
					}
					else if (arg.row.n == "SFRAC")
					{
						substream.SetScalarValue("C3ECAB21-3CAC-45C0-9709-8AD2313B8457", arg.newVal);
					}
					else if (arg.row.n == "TEMP")
					{
						substream.SetScalarValue("36ADFF82-C12D-4B22-9AC5-1E4BC786ED91", arg.newVal);
					}
					else if (arg.row.n == "PRES")
					{
						substream.SetScalarValue("AAC6DD64-F01F-4EBF-B4C8-57C4B850A9BE", arg.newVal);
					}
					else if (arg.row.n == "VLSTD-FL" && base.Top.FindRecord(arg.row.c.ToString()) is AdbComponent id)
					{
						if (substream.ArrayFindID("204dcc2a-9e06-4983-8c75-8c038ca44f2f", id) > -1)
						{
							substream.ArraySetValueAt("204dcc2a-9e06-4983-8c75-8c038ca44f2f", id, arg.newVal);
						}
						else
						{
							substream.ArrayAppend("204dcc2a-9e06-4983-8c75-8c038ca44f2f", id, arg.newVal);
						}
					}
				}
			}
			else if (arg.row.w != "DRY")
			{
				AdbPhase adbPhase = FindPhaseByAPName(substream, arg.row.ph, create: true);
				if (adbPhase != null)
				{
					OnPhaseStoreRow(adbPhase, arg);
				}
			}
		}

		private void OnPhaseStoreRow(AdbPhase phase, AdbPropertyHolder.OnStoringRdEventArg arg)
		{
			if (arg.row.n == "RHOMX")
			{
				if (arg.row.u == 37)
				{
					phase.SetScalarValue("a92c19e8-da35-44ae-9c23-d423e323e0ed", arg.newVal);
				}
				else if (arg.row.u == 38)
				{
					phase.SetScalarValue("E1F2318C-15E8-42FA-9BEB-BB4087158540", arg.newVal);
				}
			}
			else if (arg.row.n == "HMX")
			{
				if (arg.row.u == 39)
				{
					phase.SetScalarValue("f22e6757-57f1-4ddd-8322-b91c4fd6bc17", arg.newVal);
				}
