		public virtual double? GetTotalSimUtilityCost()
		{
			if (SimUtilityCost == null || SimUtilityCost.Length == 0)
			{
				return null;
			}
			double num = 0.0;
			for (int i = 0; i < SimUtilityCost.Length; i++)
			{
				num += (double)SimUtilityCost.ValueAtLocation(i);
			}
			return num;
		}

		[AdbMethodIdent("0A6FE07D-09E4-4602-BFAC-278DA5FCF2D6")]
		public void ConnectInlet(string portName, AdbStream inlet)
		{
			AdbConnection destination = inlet.Destination;
			if (destination != null && destination.Block == this)
			{
				return;
			}
			AdbConnection adbConnection = null;
			if (destination != null)
			{
				if (destination.Block == null)
				{
					adbConnection = destination;
				}
				else
				{
					destination.Block.DisconnectInlet(inlet);
					adbConnection = new AdbConnection(_top, null);
				}
			}
			else
			{
				adbConnection = new AdbConnection(_top, null);
			}
			adbConnection.SetScalarValue("8B9185BA-7F5E-47FE-83B2-6D74CE612691", this);
