		[AdbMethodIdent("C58E04BF-F274-4F4F-AA34-F53B23440128")]
		public void ConnectOutlet(string portName, AdbStream outlet)
		{
			AdbConnection source = outlet.Source;
			if (source != null && source.Block == this)
			{
				return;
			}
			AdbConnection adbConnection = null;
			if (source != null)
			{
				if (source.Block == null)
				{
					adbConnection = source;
				}
				else
				{
					source.Block.DisconnectOutlet(outlet);
					adbConnection = new AdbConnection(_top, null);
				}
			}
			else
			{
				adbConnection = new AdbConnection(_top, null);
			}
			adbConnection.SetScalarValue("8B9185BA-7F5E-47FE-83B2-6D74CE612691", this);
			adbConnection.SetScalarValue("86C17B98-CC01-4041-8D19-F70EBC0BA843", outlet);
			adbConnection.SetScalarValue("D0835727-9D32-4CD3-9E69-21BFF34AEA49", portName);
			if (Outlets == null)
			{
				Outlets = new AdbBaseArray<AdbNoId, AdbConnection>(base.Top, this);
			}
			ArrayAppend("E4CBE853-9062-4BB1-AC6F-D226CF5C9897", default(AdbNoId), adbConnection);
			outlet.SetScalarValue("B56B510F-D77C-473C-8B6A-983DF185EF5D", adbConnection);
		}

