		[AdbMethodIdent("9F01710B-A986-4DFA-8DC0-F504EAA532AF")]
		public void DisconnectInlet(AdbStream inlet)
		{
			if (Inlets == null)
			{
				return;
			}
			int length = Inlets.Length;
			for (int i = 0; i < length; i++)
			{
				AdbConnection adbConnection = (AdbConnection)Inlets.ValueAtLocation(i);
				if (adbConnection != null && adbConnection.Stream == inlet)
				{
					ArrayRemoveAtLocation("5AFCCE95-57B9-450C-81AC-9ED152BB5232", i);
					inlet.SetScalarValue("A52E13DA-789F-4675-8619-BF83C3085B61", null);
					_top.RecordMap.Remove(adbConnection.MyGuid, -1L);
					_top.NotifyOnRecordDelete(adbConnection);
					break;
				}
			}
		}

