		[AdbMethodIdent("A4BAC7E6-9877-48FA-A9F3-BECDAE4AB221", Comment1 = "Blank portName means all outlets")]
		public int CountOutlets(string portName)
		{
			int length = Outlets.Length;
			int num = length;
			if (!string.IsNullOrWhiteSpace(portName))
			{
				num = 0;
				for (int i = 0; i < length; i++)
				{
					AdbConnection adbConnection = (AdbConnection)Outlets.ValueAtLocation(i);
					if (adbConnection != null && string.Compare(adbConnection.PortName, portName, ignoreCase: true) == 0)
					{
						num++;
					}
				}
			}
			return num;
		}

		[AdbMethodIdent("518F7F30-6D40-4DD0-8643-62B4A82EBBDF", Comment1 = "Blank portName means all inlets")]
		public int CountInlets(string portName)
		{
			int length = Inlets.Length;
			int num = length;
			if (!string.IsNullOrWhiteSpace(portName))
			{
