				for (int i = 0; i < length; i++)
				{
					AdbConnection adbConnection = (AdbConnection)Inlets.ValueAtLocation(i);
					if (adbConnection != null && string.Compare(adbConnection.PortName, portName, ignoreCase: true) == 0)
					{
						num++;
					}
				}
			}
			return num;
		}

		[AdbMethodIdent("FD70A9D0-2EE9-4903-8053-54804906BDF8", Comment1 = "Get index stream for a given port", Comment2 = "Blank portName means all inlets")]
		public AdbStream GetInlet(string portName, int index)
		{
			AdbStream result = null;
			if (Inlets != null)
			{
				int length = Inlets.Length;
				int num = -1;
				for (int i = 0; i < length; i++)
				{
					AdbConnection adbConnection = (AdbConnection)Inlets.ValueAtLocation(i);
					if (adbConnection != null && (string.IsNullOrWhiteSpace(portName) || string.Compare(adbConnection.PortName, portName, ignoreCase: true) == 0))
					{
						num++;
						if (num >= index)
						{
							result = adbConnection.Stream;
							break;
						}
					}
				}
			}
			return result;
		}

		[AdbMethodIdent("8B46C3E3-5C69-4653-9D0D-E1769978C73D", Comment1 = "Get index stream for a given port", Comment2 = "Blank portName means all outlets")]
		public AdbStream GetOutlet(string portName, int index)
		{
			AdbStream result = null;
			if (Outlets != null)
			{
				int length = Outlets.Length;
				int num = -1;
				for (int i = 0; i < length; i++)
				{
					AdbConnection adbConnection = (AdbConnection)Outlets.ValueAtLocation(i);
					if (adbConnection != null && (string.IsNullOrWhiteSpace(portName) || string.Compare(adbConnection.PortName, portName, ignoreCase: true) == 0))
					{
