		protected double SumOfChildren(getEquipmentValue equipDelegate)
		{
			double num = 0.0;
			if (SubFlowsheets != null)
			{
				string[] array = subnames;
				foreach (string index in array)
				{
					AdbFlowsheet adbFlowsheet = (AdbFlowsheet)SubFlowsheets.ValueAt(index);
					if (adbFlowsheet == null || adbFlowsheet.Blocks == null)
					{
						continue;
					}
					int length = adbFlowsheet.Blocks.Length;
					for (int j = 0; j < length; j++)
					{
						AdbBlock adbBlock = (AdbBlock)adbFlowsheet.Blocks.ValueAtLocation(j);
						if (adbBlock is AdbProjectEquipment obj)
						{
							num += equipDelegate(obj);
						}
						num += adbBlock.SumOfChildren(equipDelegate);
					}
				}
			}
			return num;
		}

		protected bool IsConnectedAtOtherEnd(bool input, AdbStream proposedStream)
		{
			bool result = false;
			if (proposedStream != null)
			{
				AdbConnection adbConnection = (input ? proposedStream.Source : proposedStream.Destination);
				if (adbConnection != null && adbConnection.Stream == proposedStream)
				{
					result = true;
				}
			}
			return result;
		}

		protected bool TooManyConnections(bool input, string port, int max)
		{
			bool result = false;
			int num = 0;
			AdbBaseArray<AdbNoId, AdbConnection> adbBaseArray = (input ? Inlets : Outlets);
			if (adbBaseArray != null)
			{
				for (int i = 0; i < adbBaseArray.Length; i++)
				{
					if (((AdbConnection)adbBaseArray.ValueAtLocation(i)).PortName.Equals(port))
					{
						num++;
						if (num >= max)
						{
							result = true;
							break;
						}
					}
				}
			}
			return result;
		}

		[AdbMethodIdent("5D114378-29A9-4128-83C5-1F7A76514BB2")]
		public string ListAvailablePorts(bool input, AdbStream proposedStream)
		{
			return VirtualListAvailablePorts(input, proposedStream);
		}

		public virtual string VirtualListAvailablePorts(bool input, AdbStream proposedStream)
		{
			string text = "";
			bool flag = true;
			if ((proposedStream == null || (input ? proposedStream.Destination : proposedStream.Source) == null) && !IsConnectedAtOtherEnd(input, proposedStream))
			{
				AdbConchk[] conchk = Conchk;
				for (int i = 0; i < conchk.Length; i++)
				{
					AdbConchk adbConchk = conchk[i];
					if (input == adbConchk.isInput && (proposedStream == null || adbConchk.streamType == 0 || (proposedStream.StreamType & adbConchk.streamType) != 0) && (!adbConchk.maxConnect.HasValue || !TooManyConnections(input, adbConchk.name, adbConchk.maxConnect.Value)))
					{
						if (!flag)
						{
							text += ",";
						}
						flag = false;
						text += adbConchk.name;
					}
				}
			}
			return text;
		}

		public override void CleanUp()
		{
			SubFlowsheets = null;
			Parent = null;
			Inlets = null;
			Outlets = null;
		}

		[AdbMethodIdent("C54B44FA-8D92-4AC9-B603-F38F7EDBF681")]
		public void RemoveEquipmentBlocks()
		{
			if (SubFlowsheets != null && SubFlowsheets.Length > 0)
			{
				for (int num = SubFlowsheets.Length - 1; num >= 0; num--)
				{
					((AdbFlowsheet)SubFlowsheets.ValueAtLocation(num)).RemoveEquipmentBlocks();
				}
				AdbFlowsheet adbFlowsheet = (AdbFlowsheet)SubFlowsheets.ValueAt("Economics");
				if (adbFlowsheet != null)
				{
					_top.RecordMap.Remove(adbFlowsheet.MyGuid, -1L);
					_top.NotifyOnRecordDelete(adbFlowsheet);
					SubFlowsheets.RemoveAt("Economics");
				}
			}
		}

		[AdbMethodIdent("1FE0EB04-A43D-46F0-BCAE-7A5F5A0F1E44")]
		public string FullPath(string delimeter)
		{
			string result = "";
			AdbFlowsheet parent = Parent;
			if (parent != null)
			{
				string text = parent.FullPath(delimeter);
				result = text + (text.Equals("") ? "" : delimeter) + (string)parent.Blocks.IDAtLocation(parent.Blocks.FindValue(this));
			}
			return result;
		}

		public virtual void ExemptLocals(bool reset)
		{
		}

		[AdbMethodIdent("77FBEA26-4BB0-42F5-8442-D55F6286292B")]
		public void DeleteOutput()
		{
			ExemptLocals(reset: false);
			base.Top.ExemptFlowsheetObjects();
			DeExempt();
			if (Parent != null)
			{
				Parent.Reachable = true;
			}
			DeleteAllOutput();
			ExemptLocals(reset: true);
		}

		[AdbMethodIdent("B225CA64-0A05-41C3-93F2-53133450BD62")]
		public void DeleteSelectedOutput(int mask)
		{
			ExemptLocals(reset: false);
			base.Top.ExemptFlowsheetObjects();
			DeExempt();
			if (Parent != null)
			{
				Parent.Reachable = true;
			}
			DeleteAllOutput(mask);
			ExemptLocals(reset: true);
		}

		public void DeExempt()
		{
			base.Reachable = false;
			if (SubFlowsheets != null)
			{
				((AdbFlowsheet)SubFlowsheets.ValueAt("Simulation"))?.DeExempt();
			}
		}
	}
