		[AdbMethodIdent("77E4C457-DE26-4323-B82D-B8E4B5259440")]
		public void AddCompressorCurve(string collectionName, string curveName, AdbCompressorExpanderCurve curve)
		{
			string text = (string.IsNullOrWhiteSpace(collectionName) ? curveName : (collectionName + "__" + curveName));
			string text2 = text + "_";
			int num = 0;
			while (Curves.FindID(text) != -1)
			{
				text = text2 + num;
				num++;
			}
			Curves.Append(text, curve);
		}
