		public string GetBlockGuid(string[] paths, int index)
		{
			string result = null;
			AdbFlowsheet flowsheetForPath = GetFlowsheetForPath(paths, index);
			if (flowsheetForPath != null)
			{
				AdbBase adbBase = (AdbBase)flowsheetForPath.Blocks.ValueAt(paths[paths.Length - 1]);
				if (adbBase != null)
				{
					result = adbBase.RecordGuid();
				}
			}
			return result;
		}

		public AdbBlock GetBlockFromPath(string[] paths, int index)
		{
