			AdbFlowsheet flowsheetForPath = GetFlowsheetForPath(paths, index);
			if (flowsheetForPath != null)
			{
				result = (AdbBlock)flowsheetForPath.Blocks.ValueAt(paths[paths.Length - 1]);
			}
			return result;
		}

		public AdbSensitivity GetSensitivityFromPath(string[] paths, int index)
		{
			AdbFlowsheet flowsheetForPath = GetFlowsheetForPath(paths, index);
			if (flowsheetForPath.Sensitivity == null)
			{
				flowsheetForPath.Sensitivity = new AdbBaseArray<string, AdbSensitivity>(base.Top, this);
			}
			AdbSensitivity adbSensitivity = null;
			if (flowsheetForPath.Sensitivity.ValueAt(paths[paths.Length - 1]) == null)
			{
				adbSensitivity = new AdbSensitivity(base.Top, null);
				flowsheetForPath.Sensitivity.Append(paths[paths.Length - 1], adbSensitivity);
			}
			if (flowsheetForPath.Sensitivity.ValueAt(paths[paths.Length - 1]) == null)
			{
				return null;
			}
			AdbSensitivity adbSensitivity2 = (AdbSensitivity)flowsheetForPath.Sensitivity.ValueAt(paths[paths.Length - 1]);
			if (adbSensitivity2.rows != null)
			{
				adbSensitivity2.rows.Clear(deleteRecords: true);
			}
			if (adbSensitivity2.columnHeaders != null)
			{
				adbSensitivity2.columnHeaders.Clear(deleteRecords: true);
			}
			return adbSensitivity2;
		}

