		protected AdbFlowsheet GetFlowsheetForPath(string[] paths, int index)
		{
			AdbFlowsheet result = null;
			if (index < paths.Length)
			{
				if (index == paths.Length - 1)
				{
					result = this;
				}
				else
				{
					AdbBlock adbBlock = (AdbBlock)Blocks.ValueAt(paths[index]);
					if (adbBlock != null)
					{
						AdbFlowsheet adbFlowsheet = (AdbFlowsheet)adbBlock.SubFlowsheets.ValueAt("Simulation");
						if (adbFlowsheet != null)
						{
							result = adbFlowsheet.GetFlowsheetForPath(paths, index + 1);
						}
					}
				}
			}
			return result;
		}

		[AdbMethodIdent("F7A95DB3-4B2E-430A-B630-8105CE89BE53")]
		public void RemoveBlock(AdbBlock b)
		{
			RemoveBlockRecord(b);
		}

		private void RemoveBlockRecord(AdbBlock b)
		{
			if (b == null)
			{
				return;
			}
			if (b.Inlets != null)
			{
				for (int num = b.Inlets.Length - 1; num >= 0; num--)
				{
					AdbConnection adbConnection = (AdbConnection)b.Inlets.ValueAtLocation(num);
					if (adbConnection != null && adbConnection.Stream != null)
					{
						AdbStream stream = adbConnection.Stream;
						b.DisconnectInlet(stream);
					}
				}
			}
			if (b.Outlets != null)
			{
				for (int num2 = b.Outlets.Length - 1; num2 >= 0; num2--)
				{
					AdbConnection adbConnection2 = (AdbConnection)b.Outlets.ValueAtLocation(num2);
					if (adbConnection2 != null && adbConnection2.Stream != null)
					{
						AdbStream stream2 = adbConnection2.Stream;
						b.DisconnectOutlet(stream2);
					}
				}
			}
			int num3 = Blocks.FindValue(b);
			if (num3 == -1)
			{
				return;
			}
			if (b.SubFlowsheets != null)
			{
				string[] array = fsnames;
				foreach (string index in array)
				{
					AdbFlowsheet adbFlowsheet = (AdbFlowsheet)b.SubFlowsheets.ValueAt(index);
