		[AdbMethodIdent("09FF79F4-0A1B-46D5-B5DA-9A95258DDF4B")]
		public void RemoveStream(AdbStream s)
		{
			RemoveStreamRecord(s);
		}

		private void RemoveStreamRecord(AdbStream s)
		{
			int num = Streams.FindValue(s);
			if (num == -1)
			{
				return;
			}
			AdbConnection source = s.Source;
			if (source != null && source.Block != null)
			{
				source.Block.DisconnectOutlet(s);
			}
			AdbConnection destination = s.Destination;
			if (destination != null && destination.Block != null)
			{
				destination.Block.DisconnectInlet(s);
			}
			if (s.Substreams != null)
			{
				int length = s.Substreams.Length;
				for (int i = 0; i < length; i++)
				{
					AdbSubstream adbSubstream = (AdbSubstream)s.Substreams.ValueAtLocation(0);
					if (adbSubstream.Vapor != null)
					{
						_top.RecordMap.Remove(adbSubstream.Vapor.MyGuid, -1L);
						_top.NotifyOnRecordDelete(adbSubstream.Vapor);
					}
					if (adbSubstream.Liquid1 != null)
					{
						_top.RecordMap.Remove(adbSubstream.Liquid1.MyGuid, -1L);
						_top.NotifyOnRecordDelete(adbSubstream.Liquid1);
					}
					if (adbSubstream.Liquid2 != null)
					{
						_top.RecordMap.Remove(adbSubstream.Liquid2.MyGuid, -1L);
						_top.NotifyOnRecordDelete(adbSubstream.Liquid2);
					}
					if (adbSubstream.Solid != null)
					{
						_top.RecordMap.Remove(adbSubstream.Solid.MyGuid, -1L);
						_top.NotifyOnRecordDelete(adbSubstream.Solid);
					}
					adbSubstream.MassFractions = null;
					s.ArrayRemoveAtLocation("C690F9DD-0A30-4AE6-8055-34C0FC58C300", 0);
					_top.RecordMap.Remove(adbSubstream.MyGuid, -1L);
				}
			}
			ArrayRemoveAtLocation("74FD7DAC-6707-4CC1-80DE-36FADFA7800B", num);
			_top.RecordMap.Remove(s.MyGuid, -1L);
			_top.NotifyOnRecordDelete(s);
		}

