		[AdbMethodIdent("5E412274-E9AF-49DB-B6F3-07F990B8883F")]
		public void RemoveEquipmentBlocks()
		{
			if (Blocks == null || Blocks.Length <= 0)
			{
				return;
			}
			for (int num = Blocks.Length - 1; num >= 0; num--)
			{
				AdbBlock adbBlock = (AdbBlock)Blocks.ValueAtLocation(num);
				if (adbBlock is AdbUoBlock)
				{
					(adbBlock as AdbUoBlock).ReinitializeCostValues();
				}
				adbBlock.RemoveEquipmentBlocks();
				if (adbBlock.GetType().BaseType.Equals(typeof(AdbProjectEquipment)))
				{
					RemoveBlockRecord(adbBlock);
				}
			}
		}

