		public void DeExempt()
		{
			base.Reachable = false;
			if (Blocks != null && Blocks.Length > 0)
			{
				for (int num = Blocks.Length - 1; num >= 0; num--)
				{
					((AdbBlock)Blocks.ValueAtLocation(num)).DeExempt();
				}
			}
			if (Streams != null && Streams.Length > 0)
			{
				for (int num2 = Streams.Length - 1; num2 >= 0; num2--)
				{
					((AdbStream)Streams.ValueAtLocation(num2)).DeExempt();
				}
			}
		}

