		[AdbMethodIdent("47A2D0F2-4666-4EF3-8D67-3EC927F7CE34")]
		public void SaveObjects()
		{
			savedRecords = new Dictionary<string, AdbBaseRecord>();
			savedRecordParents = new Dictionary<string, AdbBaseRecord>();
			SaveFlowsheetObjects(this, savedRecords, savedRecordParents);
			_ = (AdbTopRecord)base.Top.TopRecord();
			SaveCaseObjects(savedRecords, savedRecordParents);
		}

		private void SaveFlowsheetObjects(AdbFlowsheet flowsheet, Dictionary<string, AdbBaseRecord> savedRecords, Dictionary<string, AdbBaseRecord> savedRecordParents)
		{
			if (flowsheet.Blocks != null)
			{
				for (int i = 0; i < flowsheet.Blocks.Length; i++)
				{
					AdbBlock adbBlock = (AdbBlock)flowsheet.Blocks.ValueAtLocation(i);
					if (adbBlock != null)
					{
						savedRecords[adbBlock.MyGuid.ToString()] = adbBlock;
						savedRecordParents[adbBlock.MyGuid.ToString()] = flowsheet;
						SaveArrayFieldObjects(adbBlock, savedRecords, savedRecordParents);
						if (adbBlock.SubFlowsheets != null && adbBlock.SubFlowsheets.ValueAt("Simulation") != null)
						{
							AdbFlowsheet adbFlowsheet = (AdbFlowsheet)adbBlock.SubFlowsheets.ValueAt("Simulation");
							savedRecords[adbFlowsheet.MyGuid.ToString()] = adbFlowsheet;
							savedRecordParents[adbFlowsheet.MyGuid.ToString()] = adbBlock;
							SaveFlowsheetObjects(adbFlowsheet, savedRecords, savedRecordParents);
						}
					}
				}
			}
			if (flowsheet.Streams != null)
			{
				for (int j = 0; j < flowsheet.Streams.Length; j++)
				{
					AdbStream adbStream = (AdbStream)flowsheet.Streams.ValueAtLocation(j);
					if (adbStream != null)
					{
						savedRecords[adbStream.MyGuid.ToString()] = adbStream;
						savedRecordParents[adbStream.MyGuid.ToString()] = flowsheet;
					}
				}
			}
			if (flowsheet.Controllers == null)
			{
				return;
			}
			for (int k = 0; k < flowsheet.Controllers.Length; k++)
			{
				AdbController adbController = (AdbController)flowsheet.Controllers.ValueAtLocation(k);
				if (adbController != null)
				{
					savedRecords[adbController.MyGuid.ToString()] = adbController;
					savedRecordParents[adbController.MyGuid.ToString()] = flowsheet;
				}
			}
		}

		public void SaveCaseObjects(Dictionary<string, AdbBaseRecord> savedRecords, Dictionary<string, AdbBaseRecord> savedRecordParents)
		{
			AdbTopRecord adbTopRecord = (AdbTopRecord)base.Top.TopRecord();
			if (adbTopRecord.Case == null || !adbTopRecord.Case.GetType().Equals(typeof(AdbAhCase)))
			{
				return;
			}
			AdbAhCase adbAhCase = (AdbAhCase)adbTopRecord.Case;
			if (adbAhCase.OilManager != null)
			{
				AdbAhOilManager oilManager = adbAhCase.OilManager;
				if (oilManager.Assays != null)
				{
					for (int i = 0; i < oilManager.Assays.Length; i++)
					{
						SaveRecord((AdbBaseRecord)oilManager.Assays.ValueAtLocation(i), oilManager, savedRecords, savedRecordParents);
					}
				}
			}
			if (adbAhCase.ReactionPackageManager != null)
			{
				AdbAhReactionManager reactionPackageManager = adbAhCase.ReactionPackageManager;
				if (reactionPackageManager.ChemistrySets != null)
				{
					for (int j = 0; j < reactionPackageManager.ChemistrySets.Length; j++)
					{
						SaveRecord((AdbBaseRecord)reactionPackageManager.ChemistrySets.ValueAtLocation(j), reactionPackageManager, savedRecords, savedRecordParents);
					}
				}
				if (reactionPackageManager.ReactionSets != null)
				{
					for (int k = 0; k < reactionPackageManager.ReactionSets.Length; k++)
					{
						SaveRecord((AdbBaseRecord)reactionPackageManager.ReactionSets.ValueAtLocation(k), reactionPackageManager, savedRecords, savedRecordParents);
					}
				}
				if (reactionPackageManager.Reactions != null)
				{
					for (int l = 0; l < reactionPackageManager.Reactions.Length; l++)
					{
						SaveRecord((AdbBaseRecord)reactionPackageManager.Reactions.ValueAtLocation(l), reactionPackageManager, savedRecords, savedRecordParents);
					}
				}
			}
			if (adbAhCase.FluidPackages != null)
			{
				for (int m = 0; m < adbAhCase.FluidPackages.Length; m++)
				{
					SaveRecord((AdbBaseRecord)adbAhCase.FluidPackages.ValueAtLocation(m), adbAhCase, savedRecords, savedRecordParents);
				}
			}
			if (adbAhCase.Analyses != null)
			{
				for (int n = 0; n < adbAhCase.Analyses.Length; n++)
				{
					SaveRecord((AdbBaseRecord)adbAhCase.Analyses.ValueAtLocation(n), adbAhCase, savedRecords, savedRecordParents);
				}
			}
		}

		public void SaveArrayFieldObjects(AdbBlock block, Dictionary<string, AdbBaseRecord> savedRecords, Dictionary<string, AdbBaseRecord> savedRecordParents)
		{
			Type type = block.GetType();
			if (type.Equals(typeof(AdbCompressor)) || type.Equals(typeof(AdbAhCompressor)))
			{
				AdbCompressor adbCompressor = (AdbCompressor)block;
				if (adbCompressor.Curves != null)
				{
					for (int i = 0; i < adbCompressor.Curves.Length; i++)
					{
						SaveRecord((AdbBaseRecord)adbCompressor.Curves.ValueAtLocation(i), adbCompressor, savedRecords, savedRecordParents);
					}
				}
			}
			else if (type.Equals(typeof(AdbPump)) || type.Equals(typeof(AdbAhPump)))
			{
				AdbPump adbPump = (AdbPump)block;
				if (adbPump.Curves != null)
				{
					for (int j = 0; j < adbPump.Curves.Length; j++)
					{
						SaveRecord((AdbBaseRecord)adbPump.Curves.ValueAtLocation(j), adbPump, savedRecords, savedRecordParents);
					}
				}
			}
			else
			{
				if (!type.Equals(typeof(AdbTraySection)) && !type.Equals(typeof(AdbAhTraySection)))
				{
					return;
				}
				AdbTraySection adbTraySection = (AdbTraySection)block;
				if (adbTraySection.SizingUtilities != null)
				{
					for (int k = 0; k < adbTraySection.SizingUtilities.Length; k++)
					{
						SaveRecord((AdbBaseRecord)adbTraySection.SizingUtilities.ValueAtLocation(k), adbTraySection, savedRecords, savedRecordParents);
					}
				}
				if (adbTraySection.Stages != null)
				{
					for (int l = 0; l < adbTraySection.Stages.Length; l++)
					{
						SaveRecord((AdbBaseRecord)adbTraySection.Stages.ValueAtLocation(l), adbTraySection, savedRecords, savedRecordParents);
					}
				}
			}
		}

		private void SaveRecord(AdbBaseRecord record, AdbBaseRecord parent, Dictionary<string, AdbBaseRecord> savedRecords, Dictionary<string, AdbBaseRecord> savedRecordParents)
		{
			if (record != null)
			{
				savedRecords[record.MyGuid.ToString()] = record;
				savedRecordParents[record.MyGuid.ToString()] = parent;
