		[AdbMethodIdent("ACD78E46-9E01-43BE-A703-B3EBC2928140")]
		public void DeleteUnusedObjects(string caseName)
		{
			HashSet<string> hashSet = new HashSet<string>();
			if (AdbTopRecord.ShouldWriteDeletedOrphans)
			{
				DebugLog.PathToFile = base.Top._filename;
			}
			foreach (AdbBaseRecord value in savedRecords.Values)
			{
				Type type = value.GetType();
				string key = value.MyGuid.ToString();
				AdbBaseRecord adbBaseRecord = (savedRecordParents.ContainsKey(key) ? savedRecordParents[key] : null);
				if (adbBaseRecord.GetType().Equals(typeof(AdbFlowsheet)))
				{
					AdbFlowsheet adbFlowsheet = ((adbBaseRecord == null) ? null : ((AdbFlowsheet)adbBaseRecord));
					if (type.Equals(typeof(AdbBlock)) || type.IsSubclassOf(typeof(AdbBlock)))
					{
						AdbBlock adbBlock = (AdbBlock)value;
						hashSet.Add(adbBlock.MyGuid.ToString());
						adbFlowsheet.RemoveBlockRecord(adbBlock);
						if (AdbTopRecord.ShouldWriteDeletedOrphans)
						{
							TraceDeletedObject(adbBlock.GetType().Name, adbBlock.ID, adbBlock.MyGuid.ToString(), "AdbFlowsheet.Blocks", adbFlowsheet.FlowsheetName);
						}
					}
					else if (type.Equals(typeof(AdbStream)) || type.IsSubclassOf(typeof(AdbStream)))
					{
						AdbStream adbStream = (AdbStream)value;
						hashSet.Add(adbStream.MyGuid.ToString());
						adbFlowsheet.RemoveStreamRecord(adbStream);
						if (AdbTopRecord.ShouldWriteDeletedOrphans)
						{
							TraceDeletedObject(adbStream.GetType().Name, adbStream.ID, adbStream.MyGuid.ToString(), "AdbFlowsheet.Streams", adbFlowsheet.FlowsheetName);
						}
					}
				}
				else if (!hashSet.Contains(adbBaseRecord.MyGuid.ToString()))
				{
					DeleteUnusedObject(value, adbBaseRecord);
					hashSet.Add(value.MyGuid.ToString());
				}
			}
			savedRecords = null;
			savedRecordParents = null;
		}

