			}
			if (flag)
			{
				_top.RecordMap.Remove(record.MyGuid, -1L);
				_top.NotifyOnRecordDelete(record);
			}
		}

		private string GetArrayElementId(object adbBaseArray, int idx)
		{
			object obj = adbBaseArray.GetType().GetMethod("IDAtLocation").Invoke(adbBaseArray, new object[1] { idx });
			if (obj == null)
			{
				return "null";
			}
			return obj.ToString();
		}

		private void TraceDeletedObject(string recordType, string recordId, string recordGuid, string arrayField, string flowsheetName = null)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("Removed Orphan ").Append(recordType).Append(": \"")
				.Append(recordId)
				.Append("\" ")
				.Append(recordGuid)
				.Append(" ")
				.Append(arrayField);
			if (flowsheetName != null)
			{
				stringBuilder.Append(" fs = ").Append(flowsheetName);
			}
			DebugLog.WriteDebug(stringBuilder.ToString());
		}
	}
