			double? num = null;
			if (Substreams != null && Substreams.Length > 0)
			{
				for (int i = 0; i < Substreams.Length; i++)
				{
					if (Substreams.ValueAtLocation(0) is AdbSubstream adbSubstream)
					{
						if (!num.HasValue)
