			base.Reachable = false;
			DeleteAllOutput();
		}

		[AdbMethodIdent("E8B69B7C-2C42-4656-B27C-4877D0188164")]
		public void DeleteSelectedOutput(int mask)
		{
			base.Top.ExemptFlowsheetObjects();
			if (Parent != null)
			{
				Parent.Reachable = true;
			}
			base.Reachable = false;
			DeleteAllOutput(mask);
		}

