		private void SetPhaseValue(string phaseName, AdbBaseArray<AdbComponent, double> phase, XmlReader rdr, AdbComponent cmpt)
		{
			string attribute = rdr.GetAttribute(phaseName);
			if (phase != null && attribute != null)
			{
				double num = double.Parse(attribute, CultureInfo.InvariantCulture);
				phase.Append(cmpt, num);
			}
		}

		protected AdbBaseArray<AdbComponent, double> ReadComponentArray(XmlReader rdr, AdbComponents componentList, string arrayGuid, string phaseArrayGuid)
		{
			AdbBaseArray<AdbComponent, double> adbBaseArray = null;
			AdbBaseArray<AdbComponent, double> adbBaseArray2 = null;
			AdbBaseArray<AdbComponent, double> adbBaseArray3 = null;
			AdbBaseArray<AdbComponent, double> adbBaseArray4 = null;
			AdbBaseArray<AdbComponent, double> adbBaseArray5 = null;
			int num = 0;
			while (rdr.Read())
			{
				if (rdr.NodeType == XmlNodeType.Element)
				{
					if (adbBaseArray == null)
					{
						adbBaseArray = new AdbBaseArray<AdbComponent, double>(base.Top, this);
						if (Vapor != null)
						{
							adbBaseArray2 = new AdbBaseArray<AdbComponent, double>(base.Top, Vapor);
						}
						if (Liquid1 != null)
						{
							adbBaseArray3 = new AdbBaseArray<AdbComponent, double>(base.Top, Liquid1);
						}
						if (Liquid2 != null)
						{
							adbBaseArray4 = new AdbBaseArray<AdbComponent, double>(base.Top, Liquid2);
						}
						if (Solid != null)
						{
							adbBaseArray5 = new AdbBaseArray<AdbComponent, double>(base.Top, Solid);
						}
					}
					if (componentList.Components != null)
					{
						int num2 = componentList.Components.FindID(rdr.GetAttribute("id"));
						if (num2 != -1)
						{
							AdbComponent adbComponent = (AdbComponent)componentList.Components.ValueAtLocation(num2);
							if (adbComponent != null)
							{
								double num3 = double.Parse(rdr.GetAttribute("v"), CultureInfo.InvariantCulture);
								adbBaseArray.Append(adbComponent, num3);
								_top.NotifyOnArraySetValueAt(this, arrayGuid, num, num3);
								num++;
								SetPhaseValue("VP", adbBaseArray2, rdr, adbComponent);
								SetPhaseValue("L1", adbBaseArray3, rdr, adbComponent);
								SetPhaseValue("L2", adbBaseArray4, rdr, adbComponent);
								SetPhaseValue("S", adbBaseArray5, rdr, adbComponent);
							}
						}
					}
				}
				if (rdr.NodeType == XmlNodeType.EndElement)
				{
					break;
				}
			}
			if (Vapor != null)
			{
				Vapor.SetActualArray(phaseArrayGuid, adbBaseArray2);
			}
			if (Liquid1 != null)
			{
				Liquid1.SetActualArray(phaseArrayGuid, adbBaseArray3);
			}
			if (Liquid2 != null)
			{
				Liquid2.SetActualArray(phaseArrayGuid, adbBaseArray4);
			}
			if (Solid != null)
			{
				Solid.SetActualArray(phaseArrayGuid, adbBaseArray5);
			}
			return adbBaseArray;
		}

		public override void CleanUp()
		{
			if (Vapor != null)
			{
				Vapor.CleanUp();
				_top.RecordMap.Remove(Vapor.MyGuid, -1L);
				_top.NotifyOnRecordDelete(Vapor);
				Vapor = null;
			}
			if (Liquid != null)
			{
				Liquid.CleanUp();
				_top.RecordMap.Remove(Liquid.MyGuid, -1L);
				_top.NotifyOnRecordDelete(Liquid);
				Liquid = null;
			}
			if (Liquid1 != null)
			{
				Liquid1.CleanUp();
				_top.RecordMap.Remove(Liquid1.MyGuid, -1L);
				_top.NotifyOnRecordDelete(Liquid1);
				Liquid1 = null;
			}
			if (Liquid2 != null)
			{
				Liquid2.CleanUp();
				_top.RecordMap.Remove(Liquid2.MyGuid, -1L);
				_top.NotifyOnRecordDelete(Liquid2);
				Liquid2 = null;
			}
			if (Accumulation != null)
			{
				Accumulation.CleanUp();
				_top.RecordMap.Remove(Accumulation.MyGuid, -1L);
				_top.NotifyOnRecordDelete(Accumulation);
				Accumulation = null;
			}
			if (PSD != null)
			{
				PSD.CleanUp();
				_top.RecordMap.Remove(PSD.MyGuid, -1L);
				_top.NotifyOnRecordDelete(PSD);
				PSD = null;
			}
			if (MassFractions != null)
			{
				MassFractions.Clear(deleteRecords: true);
				MassFractions = null;
			}
			if (ComponentAttributes != null)
			{
				ComponentAttributes.Clear(deleteRecords: true);
				ComponentAttributes = null;
			}
			if (MoleFractions != null)
			{
				MoleFractions.Clear(deleteRecords: true);
				MoleFractions = null;
			}
			if (DutyProfile != null)
			{
				DutyProfile.Clear(deleteRecords: true);
				DutyProfile = null;
			}
			base.CleanUp();
		}

		public static AdbComponent GetComponent(AdbTop top, object cmpt)
