			}
			if (GetResolvedMolarSolidFraction() >= 1.0)
			{
				return "Solid";
			}
			if ((VaporFraction ?? 0.0) > 0.0 || (VaporMassFraction ?? 0.0) > 0.0 || (LiquidFraction ?? 0.0) > 0.0 || (LiquidMassFraction ?? 0.0) > 0.0 || (SolidFraction ?? 0.0) > 0.0 || (SolidMassFraction ?? 0.0) > 0.0)
