		public static string[] ParsePath(string path)
		{
			if (path.Contains("_@"))
			{
				return path.Replace("_@", "\\").Split(bslashSplit, StringSplitOptions.RemoveEmptyEntries).Reverse()
					.ToArray();
			}
			return path.Split(dotSplit, StringSplitOptions.RemoveEmptyEntries);
		}

