		private void CleanUpFlowsheetArrayFields(AdbFlowsheet flowsheet)
		{
			if (flowsheet.Blocks != null)
			{
				List<int> list = new List<int>();
				HashSet<object> hashSet = new HashSet<object>();
				for (int i = 0; i < flowsheet.Blocks.Length; i++)
				{
					if (flowsheet.Blocks.ValueAtLocation(i) == null)
					{
						list.Add(i);
						if (ShouldWriteDeletedOrphans)
						{
							object recordId = flowsheet.Blocks.IDAtLocation(i);
							TraceDeletedObject("AdbBlock", recordId, "AdbFlowsheet.Blocks", i, flowsheet.FlowsheetName);
						}
					}
					else if (flowsheet.Blocks.IDAtLocation(i) != null && hashSet.Contains(flowsheet.Blocks.IDAtLocation(i)))
					{
						list.Add(i);
						if (ShouldWriteDeletedOrphans)
						{
							AdbBlock adbBlock = (AdbBlock)flowsheet.Blocks.ValueAtLocation(i);
							TraceDeletedObject(adbBlock.GetType().Name, adbBlock.ID, adbBlock.MyGuid.ToString(), "AdbFlowsheet.Blocks", i, flowsheet.FlowsheetName);
						}
					}
					else
					{
						hashSet.Add(flowsheet.Blocks.IDAtLocation(i));
					}
					AdbBlock adbBlock2 = (AdbBlock)flowsheet.Blocks.ValueAtLocation(i);
					if (adbBlock2 != null && adbBlock2.SubFlowsheets != null && adbBlock2.SubFlowsheets.ValueAt("Simulation") != null)
					{
						AdbFlowsheet flowsheet2 = (AdbFlowsheet)adbBlock2.SubFlowsheets.ValueAt("Simulation");
						CleanUpFlowsheetArrayFields(flowsheet2);
						CleanUpUnitOpArrayFields(adbBlock2);
					}
				}
				for (int num = list.Count - 1; num >= 0; num--)
				{
					flowsheet.Blocks.RemoveAtLocation(list[num]);
				}
			}
			if (flowsheet.Streams == null)
			{
				return;
			}
			List<int> list2 = new List<int>();
			HashSet<object> hashSet2 = new HashSet<object>();
			for (int j = 0; j < flowsheet.Streams.Length; j++)
			{
				if (flowsheet.Streams.ValueAtLocation(j) == null)
				{
					list2.Add(j);
					if (ShouldWriteDeletedOrphans)
					{
						object recordId2 = flowsheet.Streams.IDAtLocation(j);
						TraceDeletedObject("AdbStream", recordId2, "AdbFlowsheet.Streams", j, flowsheet.FlowsheetName);
					}
				}
				else if (flowsheet.Streams.IDAtLocation(j) != null && hashSet2.Contains(flowsheet.Streams.IDAtLocation(j)))
				{
					list2.Add(j);
					if (ShouldWriteDeletedOrphans)
					{
						AdbStream adbStream = (AdbStream)flowsheet.Streams.ValueAtLocation(j);
						TraceDeletedObject(adbStream.GetType().Name, adbStream.ID, adbStream.MyGuid.ToString(), "AdbFlowsheet.Streams", j, flowsheet.FlowsheetName);
					}
				}
				else
				{
					hashSet2.Add(flowsheet.Streams.IDAtLocation(j));
				}
			}
			for (int num2 = list2.Count - 1; num2 >= 0; num2--)
			{
				flowsheet.Streams.RemoveAtLocation(list2[num2]);
			}
		}

