		public void CleanUpUnitOpArrayFields(AdbBlock block)
		{
			Type type = block.GetType();
			if (type.Equals(typeof(AdbCompressor)) || type.Equals(typeof(AdbAhCompressor)))
			{
				AdbCompressor adbCompressor = (AdbCompressor)block;
				if (adbCompressor.Curves == null)
				{
					return;
				}
				List<int> list = new List<int>();
				HashSet<object> hashSet = new HashSet<object>();
				for (int i = 0; i < adbCompressor.Curves.Length; i++)
				{
					if (adbCompressor.Curves.ValueAtLocation(i) == null)
					{
						list.Add(i);
						if (ShouldWriteDeletedOrphans)
						{
							object recordId = adbCompressor.Curves.IDAtLocation(i);
							TraceDeletedObject("AdbCompressorExpanderCurve", recordId, "AdbCompressor.Curves", i);
