						{
							AdbCompressorExpanderCurve adbCompressorExpanderCurve = (AdbCompressorExpanderCurve)adbCompressor.Curves.ValueAtLocation(i);
							TraceDeletedObject("AdbCompressorExpanderCurve", adbCompressor.Curves.IDAtLocation(i), adbCompressorExpanderCurve.MyGuid.ToString(), "AdbCompressor.Curves", i);
