		private void TraceDeletedObject(string recordType, object recordId, string recordGuid, string arrayField, int idx, string flowsheetName = null)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("Removed Bad ").Append(recordType).Append(": Dup ID \"")
				.Append(recordId)
				.Append("\" ");
			stringBuilder.Append(recordGuid).Append(" ").Append(arrayField)
				.Append("[")
				.Append(idx.ToString())
				.Append("]");
			if (flowsheetName != null)
			{
				stringBuilder.Append(" fs = ").Append(flowsheetName);
			}
			DebugLog.WriteDebug(stringBuilder.ToString());
		}

		private void TraceDeletedObject(string recordType, object recordId, string arrayField, int idx, string flowsheetName = null)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("Removed Bad ").Append(recordType).Append(" \"")
				.Append(recordId)
				.Append("\" ");
			stringBuilder.Append("Null valueList element for ").Append(arrayField).Append("[")
				.Append(idx.ToString())
				.Append("]");
			if (flowsheetName != null)
			{
				stringBuilder.Append(" fs = ").Append(flowsheetName);
			}
			DebugLog.WriteDebug(stringBuilder.ToString());
		}
	}
