		public AdbBlowdownUtility(AdbTop top, Guid? existingGuid)
			: base(top, existingGuid)
		{
		}

		public AdbBlowdownUtility()
		{
		}

		[AdbMethodIdent("355CE824-6E8B-4A52-8707-68A69CD1B46A")]
		public void ClearPropertyResults(string CalculationType)
		{
			switch (CalculationType.TrimEnd())
			{
			case "ALL":
				if (DTXCalculations != null)
				{
					DTXCalculations.Clear(deleteRecords: true);
				}
				if (PTXCalculations != null)
				{
					PTXCalculations.Clear(deleteRecords: true);
				}
				if (BUBTCalculations != null)
				{
					BUBTCalculations.Clear(deleteRecords: true);
				}
				if (BUBPCalculations != null)
				{
					BUBPCalculations.Clear(deleteRecords: true);
				}
				if (DEWTCalculations != null)
				{
					DEWTCalculations.Clear(deleteRecords: true);
				}
				if (DEWPCalculations != null)
				{
					DEWPCalculations.Clear(deleteRecords: true);
				}
				if (TFLASHCalculations != null)
				{
					TFLASHCalculations.Clear(deleteRecords: true);
				}
				if (PTFLASHCalculations != null)
				{
					PTFLASHCalculations.Clear(deleteRecords: true);
				}
				if (HFLASHCalculations != null)
				{
					HFLASHCalculations.Clear(deleteRecords: true);
				}
				if (SFLASHCalculations != null)
				{
					SFLASHCalculations.Clear(deleteRecords: true);
				}
				break;
			case "DTX":
				if (DTXCalculations != null)
				{
					DTXCalculations.Clear(deleteRecords: true);
				}
				break;
			case "PTX":
				if (PTXCalculations != null)
				{
					PTXCalculations.Clear(deleteRecords: true);
				}
				break;
			case "BUBT":
				if (BUBTCalculations != null)
				{
					BUBTCalculations.Clear(deleteRecords: true);
				}
				break;
			case "BUBP":
				if (BUBPCalculations != null)
				{
					BUBPCalculations.Clear(deleteRecords: true);
				}
				break;
			case "DEWT":
				if (DEWTCalculations != null)
				{
					DEWTCalculations.Clear(deleteRecords: true);
				}
				break;
			case "DEWP":
				if (DEWPCalculations != null)
				{
					DEWPCalculations.Clear(deleteRecords: true);
				}
				break;
			case "TFLASH":
				if (TFLASHCalculations != null)
				{
					TFLASHCalculations.Clear(deleteRecords: true);
				}
				break;
			case "PTFLASH":
				if (PTFLASHCalculations != null)
				{
					PTFLASHCalculations.Clear(deleteRecords: true);
				}
				break;
			case "HFLASH":
				if (HFLASHCalculations != null)
				{
					HFLASHCalculations.Clear(deleteRecords: true);
				}
				break;
			case "SFLASH":
				if (SFLASHCalculations != null)
				{
					SFLASHCalculations.Clear(deleteRecords: true);
				}
				break;
			}
		}
	}
