	internal static class PsvValveDesignationHelpers
	{
		internal static string GetFullDesignation(double inFlange, int orifice, double outFlange)
		{
			string text = null;
			string text2 = null;
			text2 = (double.IsNaN(inFlange) ? "" : _GetFormattedFlangeSizeInInches(inFlange));
			text = text2;
			text = text + " " + orifice switch
			{
				0 => "D", 
				1 => "E", 
				2 => "F", 
				3 => "G", 
				4 => "H", 
				5 => "J", 
				6 => "K", 
				7 => "L", 
				8 => "M", 
				9 => "N", 
				10 => "P", 
				11 => "Q", 
				12 => "R", 
				13 => "T", 
				_ => "*", 
			};
			text2 = (double.IsNaN(outFlange) ? "" : _GetFormattedFlangeSizeInInches(outFlange));
			return text + " " + text2;
		}

		private static string _GetFormattedFlangeSizeInInches(double inMeters)
		{
			double num = inMeters / 0.0254;
			double num2 = Math.Truncate(num);
			decimal num3 = Math.Round((decimal)(num - num2), 4);
			string text = string.Empty;
			bool flag = num3 != 0.0m;
			if (num3 == 0.75m)
			{
				text = "3/4";
			}
			else if (num3 == 0.5m)
			{
				text = "1/2";
			}
			else if (num3 == 0.25m)
			{
				text = "1/4";
			}
			else if (num3 != 0.0m)
			{
				flag = false;
			}
			if (flag)
			{
				return ((num2 > 0.0) ? ((int)num2 + " ") : "") + text;
			}
			return $"{num:G6}";
		}
	}
